```cpp
#include <unordered_map>
#include <mutex>
#include <condition_variable>

class Cache {
public:
    void put(const std::string& key, const std::string& value, size_t ttl) {
        // ... handle expiration and memory pressure here ...
        std::unique_lock<std::mutex> lock(m_);
        cache_[key] = CacheEntry{value, std::chrono::steady_clock::now() + std::chrono::seconds(ttl)};
    }

    std::optional<std::string> get(const std::string& key) {
        // ... handle expiration and memory pressure here ...
        std::unique_lock<std::mutex> lock(m_);
        auto it = cache_.find(key);
        if (it != cache_.end() && it->second.expiration > std::chrono::steady_clock::now()) {
            return it->second.value;
        }
        return {};
    }
private:
    struct CacheEntry {
        std::string value;
        std::chrono::steady_clock::time_point expiration;
    };

    std::unordered_map<std::string, CacheEntry> cache_;
    std::mutex m_;
};
```

