// Define log4cxx logger instance (Assuming log4cxx::Logger is available)
static log4cxx::LoggerPtr LOGGER(log4cxx::Logger::getLogger("RandomEngine"));

class RandomEngine {
public:
    explicit RandomEngine(uint64_t seed = std::random_device{}());
    int32_t generate32();
    int64_t generate64();
    void generateBatch32(std::vector<int32_t>& numbers, size_t count);
    void generateBatch64(std::vector<int64_t>& numbers, size_t count);

private:
    std::mt19937_64 engine;  // Mersenne Twister engine
};

RandomEngine::RandomEngine(uint64_t seed) : engine(seed) {
    if (seed == 0) {
        seed = std::random_device{}();
    }
    LOG4CXX_INFO(LOGGER, "Seed: " << seed);
}

int32_t RandomEngine::generate32() {
    // Use engine.discard(64); to discard the first 64 results if desired
    return engine();
}

int64_t RandomEngine::generate64() {
    return engine.extract(std::mt19937::result_type());
}

void RandomEngine::generateBatch32(std::vector<int32_t>& numbers, size_t count) {
    auto generator = [this]() -> int32_t { return this->generate32(); };
    std::thread threads[count];
    for (size_t i = 0; i < count; ++i) {
        threads[i] = std::thread(generator);
    }
    for (auto& thread : threads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
    numbers.resize(count);
    std::transform(threads.begin(), threads.end(), numbers.begin(), [](std::thread t) -> int32_t { return t.get_id(); });  // Return the ID of the thread for debugging purposes
}

