function fetchThemeFromApi(id) {
  return new Promise((resolve, reject) => {
    axios.get(`${API_URL}/themes/${id}`)
      .then(response => resolve(response.data))
      .catch(error => {
        if (error.response && error.response.status === 404) {
          // Handle not found errors gracefully, e.g., by returning a default theme or updating the cache with a placeholder theme
          const defaultTheme = { id, name: 'Default', colorScheme: {} };
          cache.setex(id, 60 * 60, JSON.stringify(defaultTheme)); // Cache placeholder theme data for an hour (in seconds)
          resolve(defaultTheme);
        } else {
          reject(error);
        }
      });
  });
}
