import time
from typing import Callable

def verify_token(token: str, server_endpoint: str, on_error: Callable[[str], None] = lambda e: print(f'Error verifying token: {e}')):
    while True:
        try:
            response = requests.get(server_endpoint + f'?token={token}', timeout=5)
            if not response.ok:
                raise Exception('Invalid response from server')
            if int(time.time()) > int(response.json()['expiration']) or token != response.json()['token']:
                on_error(f'Token has expired or is invalid')
                return False
            return True
        except Exception as e:
            time.sleep(min((time.time() - (response.elapsed.total_seconds() if response.elapsed else 0)) * 2 + random.uniform(0, 1)))
            on_error(str(e))

def token_verifier():
