from time import sleep
import random

def retry(function, max_attempts=5, delay=1.0):
    for i in range(max_attempts):
        try:
            return function()
        except Exception as e:
            sleep(delay * (2 ** i) + random.uniform(0, delay))
    raise Exception('Retry limit exceeded')
