    public function __construct(int $maxAttempts, float $initialBackoff, float $multiplier) {
        // ...
    }

    public function attempt(callable $callback): mixed {
        $attempt = 0;
        $backoff = $this->initialBackoff;

        do {
            try {
                return $callback();
            } catch (\Exception $e) {
                if ($attempt >= $this->maxAttempts) {
                    throw $e;
                }

                usleep($backoff * pow(2, $attempt));
                $attempt++;
                $backoff *= $this->multiplier;
            }
        } while (true);
    }
