using System;
using System.Collections.Concurrent;
using System.Data;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using RestSharp;
using log4net;
using Dapper;

public class PasswordUpdater
{
    private readonly ILog _log = LogManager.GetLogger(typeof(PasswordUpdater));
    private readonly string _imsApiBaseUrl;
    private readonly IDbConnection _dbConnection;
    private readonly ConcurrentDictionary<string, bool> _passwordUpdateInProgress;

    public PasswordUpdater(string imsApiBaseUrl, IDbConnection dbConnection)
    {
        _imsApiBaseUrl = imsApiBaseUrl;
        _dbConnection = dbConnection;
        _passwordUpdateInProgress = new ConcurrentDictionary<string, bool>();
    }

    public async Task UpdatePassword(string userId, string newPassword)
    {
        if (!ValidatePassword(newPassword))
            throw new ArgumentException("Invalid password");

        lock (_passwordUpdateInProgress)
        {
            if (_passwordUpdateInProgress.ContainsKey(userId))
                throw new InvalidOperationException("Password update in progress for user.");

            _passwordUpdateInProgress[userId] = true;
        }

        try
        {
            var client = new RestClient($"{_imsApiBaseUrl}/users/{userId}/password");

            await UpdateLocalDatabase(userId, newPassword);

            var request = new RestRequest(Method.PUT) { AddHeader("Authorization", "Bearer <your-auth-token>") };
            request.AddParameter("application/json", new { NewPassword = HashPassword(newPassword) }, ParameterType.RequestBody);
            IRestResponse response = await client.ExecuteAsync(request);

            if (response.IsSuccessful)
            {
                _passwordUpdateInProgress.TryRemove(userId, out _);
                Console.WriteLine($"Updated password for user '{userId}'.");
            }
            else
            {
                _log.ErrorFormat("Failed to update password for user '{userId}': {StatusCode}: {StatusDescription}", response.StatusCode, response.StatusDescription);

                await RollbackLocalDatabase(userId);
                _passwordUpdateInProgress.TryRemove(userId, out _);

                throw new Exception($"Failed to update password for user '{userId}'.");
            }
        }
        catch (Exception ex)
        {
            _log.ErrorFormat("Error updating password for user '{userId}': {ExceptionMessage}", ex.Message);

            await RollbackLocalDatabase(userId);
            _passwordUpdateInProgress.TryRemove(userId, out _);

            throw;
        }
    }

    private bool ValidatePassword(string password)
    {
