        return true;
    }

    private string HashPassword(string password)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] hashedBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
            return BitConverter.ToString(hashedBytes).Replace("-", "").ToLower();
        }
    }

    private async Task UpdateLocalDatabase(string userId, string newPassword)
    {
        using (IDbTransaction transaction = _dbConnection.BeginTransaction())
        {
            try
            {
                await _dbConnection.ExecuteAsync("UPDATE Users SET Password=@password WHERE UserId=@userId", new { password = HashPassword(newPassword), userId }, transaction);
                transaction.Commit();
            }
            catch (Exception ex)
            {
                _log.ErrorFormat("Error updating local database for user '{userId}': {ExceptionMessage}", ex.Message);
                transaction.Rollback();
                throw;
            }
        }
    }

    private async Task RollbackLocalDatabase(string userId)
    {
        using (IDbTransaction transaction = _dbConnection.BeginTransaction())
        {
            try
            {
                await _dbConnection.ExecuteAsync("UPDATE Users SET Password=NULL WHERE UserId=@userId", new { userId }, transaction);
                transaction.Commit();
            }
            catch (Exception ex)
            {
                _log.ErrorFormat("Error rolling back local database for user '{userId}': {ExceptionMessage}", ex.Message);
                transaction.Rollback();
                throw;
            }
        }
    }
}
