[' ```c
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
#include <mutex>
#include <atomic>
#include <boost/asio.hpp>
#include <boost/filesystem.hpp>
#include <boost/json.hpp>
#include <memory>
#include <sstream>

std::atomic_int g_errorCount(0);
std::mutex g_errorLogMutex;
void logError(const std char* message) {
    if (++g_errorCount > 100) {
        throw std::runtime_error("Excessive errors encountered.");
    }
    std::lock_guard<std::mutex> lock(g_errorLogMutex);
    std::cout << "Error: " << message << std::endl;
}

enum class ErrorCategory {
    NetworkTimeout,
    IODisabled,
    ParseFailure,
    MemoryExhaustion,
    InvalidData
};

struct ResourceBundle {
    std::vector<std::string> items;
};

class ResourceLoader {
public:
    explicit ResourceLoader(const char* serverUrl) : ioService_(io_service_), strand_(ioService_) {}

    void loadResourceBundle(const char* serverUrl, int* itemCount, void (*logger)(const char* message)) {
        this->serverUrl_ = serverUrl;
        this->itemCount_ = itemCount;
        this->logger_ = logger;

        boost::asio::ip::tcp::resolver resolver(ioService_);
        boost::asio::ip::tcp::resolver::query query(boost::asio::ip::tcp::v4(), serverUrl);
        auto const results = resolver.resolve(query);

        boost::asio::streambuf requestBuffer;
        std::ostream requestStream(&requestBuffer);
        requestStream << "GET /resource-bundle HTTP/1.1\r\nHost: " << serverUrl << "\r\nConnection: close\r\n\r\n";

        boost::asio::streambuf responseBuffer;
        std::ostream responseStream(&responseBuffer);
        boost::asio::ip::tcp::socket socket(ioService_);
        boost::asio::connect(socket.lowest_layer(), results.begin()->endpoint());

        boost::asio::write(socket, requestBuffer);

        boost::asio::read_until(socket, responseBuffer, "\r\n\r\n");

        if (responseStream.eof()) {
            logError("Server unavailable.");
            return;
        }

        int httpStatusCode = 0;
        std::istringstream iss(std::string(boost::asio::buffer_cast<const char*>(responseBuffer.data()), responseBuffer.size()));
        std::string httpStatusLine;
        std::getline(iss, httpStatusLine);
        std::sscanf(httpStatusLine.c_str(), "%d", &httpStatusCode);

        if (httpStatusCode != 200) {
            logError("Non-200 status code received.");
            return;
        }

        boost::asio::read_until(socket, responseBuffer, "\r");

        auto resourceBundleJson = boost::json::parse(boost::asio::buffer_cast<const char*>(responseBuffer.data()), responseBuffer.size());
        if (!resourceBundleJson.is_array()) {
            logError("Invalid JSON data received.");
            return;
        }

        ResourceBundle& resourceBundle = getResourceBundle();
        resourceBundle.items.clear();

        for (const auto& item : resourceBundleJson.as_array()) {
            if (!item.is_string()) {
                logError("Invalid JSON data received.");
                continue;
            }
            resourceBundle.items.push_back(item.as_string());
        }

        *itemCount = static_cast<int>(resourceBundle.items.size());
    }

private:
    ResourceLoader(const ResourceLoader&) = delete;
    ResourceLoader& operator=(const ResourceLoader&) = delete;

    boost::asio::io_service ioService_;
    boost::asio::io_context::strand strand_;
    const char* serverUrl_;
    int* itemCount_;
    void (*logger_) (const char* message);

    static std::shared_ptr<ResourceBundle> getResourceBundle() {
        static std::mutex resourceMutex;
        static std::shared_ptr<ResourceBundle> resourceBundle(std::make_shared<ResourceBundle>());
        std::unique_lock<std::mutex> lock(resourceMutex);
        return resourceBundle;
    }
};

int* loadResourceBundle(const char* serverUrl, int* itemCount, void (*logger)(const char* message)) {
    auto loader = std::make_unique<ResourceLoader>(serverUrl);
    loader->loadResourceBundle(serverUrl, itemCount, logger);
    return itemCount;
}
```

