#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <random stone.h> // For random number generation
#include <stdlib.h> // For exit and free functions
#include <string.h> // For memset function

#define AES_KEY_SIZE 32
#define AES_IV_SIZE 16
#define PBKDF2_ITERATIONS 64000
#define SALT_LENGTH 8

typedef struct CipherContext {
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[AES_IV_SIZE];
} CipherContext;

int InitSecureCipher(const char *password, CipherContext **cipher_context) {
    // Allocate memory for the context structure and set it to zero
    if (!(*cipher_context = malloc(sizeof(CipherContext)))) {
        perror("malloc");
        return 1;
    }
    memset(*cipher_context, 0, sizeof(CipherContext));

    // Generate random IV
    if (RAND_bytes((*cipher_context)->iv, AES_IV_SIZE) <= 0) {
        perror("RAND_bytes");
        free(*cipher_context);
        return 1;
    }

    // Derive encryption key using PBKDF2 with SHA-256 and the provided password
    unsigned char salt[SALT_LENGTH];
    if (RAND_bytes(salt, SALT_LENGTH) <= 0) {
        perror("RAND_bytes");
        free(*cipher_context);
        return 1;
    }

    uint8_t prk[AES_KEY_SIZE];
    int key_len = PBKDF2(password, strlen(password), salt, SALT_LENGTH, PBKDF2_ITERATIONS, EVP_sha256(), prk, AES_KEY_SIZE);
    if (key_len <= 0) {
        perror("PBKDF2");
        free(*cipher_context);
        return 1;
    }

    // Copy derived key to the context structure
    memcpy((*cipher_context)->key, prk, AES_KEY_SIZE);

    return 0;
}
