            return null;
        }

        return process;
    }

    // Helper methods

    private async Task<HttpResponseMessage> CallExternalValidationApiAsync(string endpoint, string apiKey, string filePath)
    {
        var client = new HttpClient();
        var formData = new FormUrlEncodedContent(new[]
        {
            new KeyValuePair<string, string>("file", File.ReadAllBytes(filePath), MediaTypeNames.Application.Octet),
            new KeyValuePair<string, string>("apiKey", apiKey)
        });

        var retryAttempts = 3;
        for (int i = 0; i < retryAttempts; i++)
        {
            try
            {
                return await client.PostAsync(endpoint, formData);
            }
            catch (Exception ex)
            {
                if (i == retryAttempts - 1) throw;
                Console.WriteLine($"Transient error while calling the external validation API. Retrying in {Math.Pow(2, i + 1)} seconds...");
                await Task.Delay(Math.Pow(2, i + 1) * 1000);
            }
        }

        throw new Exception("Failed to contact the external validation API after multiple retries.");
    }

    private void LogError(string message, Exception exception = null)
    {
        // Implement error logging mechanism based on provided criteria (e.g., categorize errors, prioritize recovery actions)
        Console.WriteLine($"Error: {message}");
        if (exception != null)
            Console.WriteLine($"\nException details:\n{exception.Message}\nStack trace:\n{exception.StackTrace}");
    }
}
