typedef struct {
    const char *host;
    int port;
    const char *ssl_cert;
    const char *ssl_key;
} Config;

typedef struct UserSession {
    int id;
    char username[256];
    // Add other user data as necessary
} UserSession;

int init_service(Config config, LogFunction log, SSL_CTX* ssl_ctx, UserSession **session) {
    int status = 0;
    int sockfd;
    struct addrinfo hints, *server_info, *p;

    // Validate configuration
    if (!json_object_get_string(config.host)) {
        log("Error: Missing host configuration.");
        return -1;
    }
    if (!json_object_get_int(config.port)) {
        log("Error: Missing port configuration.");
        return -1;
    }
    if (!config.ssl_cert || !config.ssl_key) {
        log("Error: Missing SSL certificate or key.");
        return -1;
    }

    // Initialize user session object
    *session = malloc(sizeof(UserSession));
    memset(*session, 0, sizeof(UserSession));

    // Set up hints for getaddrinfo()
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;   // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    // Look up the domain name or IP address
    status = getaddrinfo(config.host, NULL, &hints, &server_info);
    if (status != 0) {
        log("Error: Failed to resolve host.");
        return -1;
    }

    // Loop through all the results and connect to the first one we can
    for(p = server_info; p != NULL; p = p->ai_next) {
        if ((sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol)) == -1) {
            log("Error: Failed to create socket.");
            continue;
        }

        // Connect to the server
        status = connect(sockfd, p->ai_addr, p->ai_addrlen);
        if (status == 0) {
            break;   // Successfully connected. No need to try the next one.
        }

        close(sockfd);    // Socket failed - close it and move on to the next.
    }

    if (!p) {
        log("Error: Unable to connect.");
        return -1;
    }

    freeaddrinfo(server_info);   // No longer needed

    // SSL handshake
    int enabled = (config.ssl_cert && config.ssl_key);
    if (enabled) {
        SSL *ssl = SSL_new(ssl_ctx);
        SSL_set_fd(ssl, sockfd);
        status = SSL_connect(ssl);
        if (status <= 0) {
            log("Error: Failed to establish SSL connection.");
            return -1;
        }
    }

    // Perform health check on the network socket
    // Implement your logic here based on the requirements

    // Validation successful, return success code
    return 0;
}
