```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

namespace EncryptionLibrary
{
    public class DecryptAndDeserializeService
    {
        private readonly ILogger<DecryptAndDeserializeService> _logger;
        private readonly IMemoryCache _cache;
        private readonly string _kmsEndpointUrl;

        public DecryptAndDeserializeService(ILogger<DecryptAndDeserializeService> logger, IMemoryCache cache, string kmsEndpointUrl)
        {
            _logger = logger;
            _cache = cache;
            _kmsEndpointUrl = kmsEndpointUrl;
        }

        public async Task<T> DecryptAndDeserializeAsync<T>(string filePath)
        {
            if (string.IsNullOrEmpty(filePath)) throw new ArgumentNullException(nameof(filePath));

            var keyAndIv = await FetchKeyAsync(_kmsEndpointUrl);
            var encryptedData = File.ReadAllBytes(filePath);
            var decryptedData = DecryptData(encryptedData, keyAndIv.Key, keyAndIv.IV);
            var deserializedObject = JsonConvert.DeserializeObject<T>(decryptedData);

            return deserializedObject;
        }

        private async Task<(string Key, byte[] IV)> FetchKeyAsync(string kmsEndpointUrl)
        {
            // Implement retry logic and caching mechanisms
            var cachedKey = _cache.Get(kmsEndpointUrl);
            if (cachedKey != null) return (cachedKey as string, cachedKey as byte[]);

            using (var httpClient = new HttpClient())
            {
                // Make API call to the KMS service for key and IV
                var response = await httpClient.GetAsync(kmsEndpointUrl);
                if (!response.IsSuccessStatusCode)
                {
                    _logger.LogError($"Failed to fetch encryption keys from {kmsEndpointUrl}: {response.StatusCode}");
                    throw new Exception("Failed to fetch encryption keys");
                }

                var keyAndIvResponse = JsonConvert.DeserializeObject<KeyAndIVResponse>(await response.Content.ReadAsStringAsync());
                _cache.Set(kmsEndpointUrl, keyAndIvResponse.Key, new MemoryCacheEntryOptions().ExpireAfter(TimeSpan.FromMinutes(5)));
                return (keyAndIvResponse.Key, keyAndIvResponse.IV);
            }
        }

        private byte[] DecryptData(byte[] encryptedData, string key, byte[] iv)
        {
            // Implement decryption logic using AES algorithm and provided key and IV
            using (var aes = Aes.Create())
            {
                aes.Key = Convert.FromBase64String(key);
                aes.IV = iv;
                var decryptor = aes.CreateDecryptor();
                return Decryptor.Decrypt(encryptedData, decryptor);
            }
        }
    }

    public class KeyAndIVResponse
    {
        public string Key { get; set; }
        public byte[] IV { get; set; }
    }
}
```

