class ApiClient:
    def __init__(self, api_key, base_url):
        self.session = requests.Session()
        self.api_key = api_key
        self.base_url = base_url

    def get(self, endpoint):
        response = self.session.get(self.base_url + endpoint)
        if response.status_code != 200:
            raise Exception(f"API error: {response.text}")
        return response.json()

class KickstartTemplateProcessor:
    def __init__(self, template_path, env):
        self.env = env
        self.template = self.env.get_template(template_path)

    def process(self, data):
        return self.template.render(data)

class Encryptor:
    @staticmethod
    def encrypt(password, key=os.urandom(32)):
        cipher = AES.new(key, AES.MODE_EAX)
        nonce = cipher.nonce
        encrypted_data = cipher.encrypt(padding.pad(password.encode(), padding.PKCS7(16).name), nonce=nonce)
        return {
            'value': encrypted_data,
            'iv': nonce,
        }

    @staticmethod
    def decrypt(encrypted_data):
        key = Random.new().read(32)
        cipher = AES.new(key, AES.MODE_EAX, iv=encrypted_data['iv'])
        decrypted_data = cipher.decrypt(encrypted_data['value'])
        return padding.unpad(decrypted_data, padding.PKCS7(16).name)

class Application:
