public class DynamicQueryExecutionService : IDynamicQueryExecutionService
{
    private readonly IConfiguration _configuration;
    private readonly ConnectionMultiplexer _redis;
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<DynamicQueryExecutionService> _logger;
    private readonly ConcurrentDictionary<string, Func<IDbConnection>> _connectionCache = new();

    public DynamicQueryExecutionService(IConfiguration configuration, IServiceScopeFactory scopeFactory)
    {
        _configuration = configuration;
        _scopeFactory = scopeFactory;
        _logger = scopeFactory.CreateScope().ServiceProvider.GetRequiredService<ILogger<DynamicQueryExecutionService>>();
        _redis = ConnectionMultiplexer.Connect(_configuration["Redis:ConnectionString"]);
    }

    public async Task ExecuteCommandAsync(string connectionString, string commandText, DynamicParameters parameters, TimeSpan timeout, CancellationToken cancellationToken)
    {
        if (!IsValidConnectionString(connectionString))
        {
            _logger.LogError($"Invalid connection string: {connectionString}");
            throw new ArgumentException("Invalid connection string format.");
        }

        if (commandText == null)
        {
            _logger.LogError($"Null or empty command text.");
            throw new ArgumentNullException(nameof(commandText));
        }

        var dbConnection = GetDbConnection(connectionString);

        try
        {
            await dbConnection.OpenAsync(cancellationToken).ConfigureAwait(false);

            using (var transaction = dbConnection.BeginTransaction(IsolationLevel.ReadCommitted))
            {
                await dbConnection.ExecuteAsync(commandText, parameters, timeout, cancellationToken, transaction: transaction).ConfigureAwait(false);
                transaction.Commit();
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"Command execution error: {ex.Message}");

            if (IsTransientError(ex))
            {
                await Task.Delay(TimeSpan.FromSeconds(_configuration["Retries:DelayBeforeRetry"]), cancellationToken).ConfigureAwait(false);
                await ExecuteCommandAsync(connectionString, commandText, parameters, timeout, cancellationToken).ConfigureAwait(false);
            }
            else
            {
                throw;
            }
        }
    }

    private Func<IDbConnection> GetDbConnection(string connectionString)
    {
        if (_connectionCache.TryGetValue(connectionString, out var connectionFactory)) return connectionFactory;

        var connection = _scopeFactory.CreateScope().ServiceProvider.GetRequiredService<IDbConnection>(connectionString);
        connection.Open();

        void CloseConnection() => connection.Close();
        Func<IDbConnection> newFactory = () => connection;

        _connectionCache[connectionString] = newFactory;
        return newFactory;
    }

    private bool IsValidConnectionString(string connectionString)
    {
        // Implement strict security and compliance checks on the connection string here
        // E.g., validate that the connection string points to a valid database instance, etc.
        return true;
    }

