    // Load and execute the script, handling errors and retries
    const cachedScript = cache.get(script.src);
    if (cachedScript) {
      // Use the cached script if available
      headElement.appendChild(cachedScript);
    } else {
      // Fetch the script from the external API for loading
      const response = await fetchScript(script);

      if (!response.ok) {
        // Handle error cases, including validation errors and server unavailability
        handleError(response);
        return;
      }

      // Add the script to the head element
      const newScriptElement = document.createElement('script');
      newScriptElement.src = response.url;
      newScriptElement.type = script.type;
      newScriptElement.defer = script.defer;
      newScriptElement.async = script.async;
      headElement.appendChild(newScriptElement);

      // Update the cache for future requests
      if (!script.lazyLoad) {
        cache.set(script.src, newScriptElement);
      }
    }
  } catch (error) {
    logger.error(`Error loading script ${script.scriptId}:`, error);
    // Implement exponential backoff strategy here
  }
}

function validateScript(scriptObj) {
