        .send()
        .await?
        .error_for_status()?;
    let certificate = response.json::<Certificate>().await?;
    CERTIFICATES.write().insert(certificate.id.clone(), certificate);
    Ok(HttpResponse::Ok().body(serde_json::to_string(&certificate).unwrap()))
