2. C utility (JPEG to PDF converter):

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

#define MAX_BUFFER_SIZE 1024*1024 // 1MB buffer size
char buffer[MAX_BUFFER_SIZE];
int fd_input, fd_output;
pid_t child_pid;

void handle_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

void sig_handler(int signo) {
    write(fd_input, "\x04", 1); // Send Interrupt signal to third-party tool
    kill(child_pid, SIGINT);
    waitpid(child_pid, NULL, 0);
}

int main() {
    setbuf(stdout, NULL);
    signal(SIGINT, sig_handler);

    fd_input = open("input.jpeg", O_RDONLY);
    if (fd_input < 0) {
        handle_error("Error opening input file");
    }

    fd_output = open("output.pdf", O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IXUSR);
    if (fd_output < 0) {
        handle_error("Error creating output file");
    }

    child_pid = fork();
    if (child_pid < 0) {
        handle_error("Error forking process");
    } else if (child_pid == 0) { // Child process
        close(fd_input);
        dup2(fd_output, STDOUT_FILENO);
        execl("/path/to/third-party-tool", "/path/to/third-party-tool", NULL);
    } else { // Parent process
        ssize_t bytes_read;
        while ((bytes_read = read(fd_input, buffer, MAX_BUFFER_SIZE)) > 0) {
            write(fd_output, buffer, bytes_read);
        }
        if (bytes_read < 0) {
            handle_error("Error reading from input file");
        }
        close(fd_input);
        close(fd_output);
    }
    return 0;
}
```

