use std::sync::mpsc::channel;
use tokio::spawn;

pub fn spawn_async(f: Box<FnOnce() -> () + Send>) {
    let (tx, rx) = channel();
    tx.send(()).unwrap();

    spawn(move || {
        f();
        rx.recv().unwrap();
    });
}
