}

LLVMValue* generateLLVMIRFromBundle(const char* serverUrl, const char* filePath, int* itemCount, void (*logger)(const char* message)) {
    std::unique_ptr<CURL> curl(curl_easy_init());
    if (!curl) {
        logError("Failed to initialize curl");
        return nullptr;
    }

    curl_easy_setopt(curl.get(), CURLOPT_URL, serverUrl);
    curl_easy_setopt(curl.get(), CURLOPT_WRITEFUNCTION, writeFunction);
    // Configure other options as needed (e.g., timeout, retry policy)

    std::string resourceBundle = fetchResourceBundle(serverUrl, std::move(curl));
    if (resourceBundle.empty()) {
        logError("Failed to fetch the resource bundle");
        return nullptr;
    }

    antlr4::ANTLRInputStream inputStream(resourceBundle);
    std::unique_ptr<antlr4::CharStream> charStream(inputStream.getTokenStream());
    ANTLR4_FILE_POSITION filePos = inputStream.getSourceStart();
    auto parserRuleStream = createParserRuleStream(filePos, filePath);

    if (!parserRuleStream) {
        logError("Failed to create the parser rule stream");
        return nullptr;
    }

    int totalItems = 0;
    LLVMValueRef llvmIR = parseAndGenerateLLVMIR(parserRuleStream.get(), &totalItems);
    if (!llvmIR) {
        logError("Failed to generate LLVM IR code");
        return nullptr;
    }

    *itemCount = totalItems;
    return llvmIR;
}

