[" Here's a high-level outline of the `SecureDataEncryptor` library in C#, using AES-256-CBC with PBKDF2 for key derivation. Note that this code does not include system integration, caching mechanisms, or error handling as those aspects are complex and specific to your application's context.

```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.IO;

namespace SecureDataEncryptor
{
    public class Encryptor
    {
        private readonly Rfc2898DeriveBytes _kdf = new Rfc2898DeriveBytes(256, 64, SHA256.Create());

        public byte[] Encrypt(string password, byte[] data)
        {
            var salt = RandomSalt(); // Implement RandomSalt method for generating a random salt
            var key = DeriveKey(password, salt);
            var iv = RandomIV(); // Implement RandomIV method for generating a random IV

            using (var aes = AES.Create())
            {
                aes.Key = key;
                aes.IV = iv;
                using (var encryptor = aes.CreateEncryptor())
                {
                    using (var memoryStream = new MemoryStream())
                    {
                        using (var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write))
                        {
                            cryptoStream.Write(data, 0, data.Length);
                            cryptoStream.FlushFinalBlock();
                            return Combine(iv, memoryStream.ToArray());
                        }
                    }
                }
            }
        }

        private byte[] DeriveKey(string password, byte[] salt)
        {
            _kdf.Salt = salt;
            return _kdf.GetBytes(32); // Adjust the size according to your needs
        }

        private byte[] RandomIV()
        {
            var random = new RNGCryptoServiceProvider();
            var iv = new byte[Aes.BlockSize / 8];
            random.GetBytes(iv);
            return iv;
        }

        private static byte[] Combine(byte[] first, byte[] second)
        {
            var result = new byte[first.Length + second.Length];
            Buffer.BlockCopy(first, 0, result, 0, first.Length);
            Buffer.BlockCopy(second, 0, result, first.Length, second.Length);
            return result;
        }
    }
}
```

This outline provides a basic structure for the encryption library. To meet your operational context requirements, you'll need to incorporate caching mechanisms, system integration, error handling, and performance optimization strategies as needed."]

