#include <stdlib.h>

bool ValidateOAuth2AccessToken(const char* json) {
  json_t *root;
  root = json_loads(json, 0, NULL);
  if (!root || !json_is_object(root)) {
    // Invalid JSON or not an object
    return false;
  }

  const char* audience = getenv("OAUTH2_AUDIENCE");
  const char* token_audience = json_object_get(root, "aud");

  if (strcmp(token_audience, audience) != 0) {
    // Audience does not match the expected value
    return false;
  }

  json_t *exp = json_object_get(root, "exp");
  time_t now = time(NULL);

  if (!json_is_number(exp)) {
    // exp is not a number
    return false;
  }

  double exp_value = json_number_value(exp);
  if (now > exp_value) {
    // Expiration time has passed
    return false;
  }

  json_t *iss = json_object_get(root, "iss");
  if (!json_is_string(iss)) {
    // iss is not a string
    return false;
  }

  const char* issuer = getenv("OAUTH2_ISSUER");
  if (strcmp(issuer, json_string_value(iss)) != 0) {
    // Issuer does not match the expected value
    return false;
  }

  json_t *iat = json_object_get(root, "iat");
  if (!json_is_number(iat)) {
    // iat is not a number
    return false;
  }

  double iat_value = json_number_value(iat);
  if (now - iat_value > 60 * 5) {
    // Issued time was more than 5 minutes ago
    return false;
  }

  json_t *nbf = json_object_get(root, "nbf");
  if (!json_is_number(nbf)) {
    // nbf is not a number
    return false;
  }

  double nbf_value = json_number_value(nbf);
  if (now < nbf_value) {
    // Not before time has not yet passed
    return false;
  }

  return true;
}
```

