<?php

// Database connection (using PDO for better performance)
$db = new PDO("mysql:host=localhost;dbname=clinics", "username", "password");
$db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

// Lock table to enforce rate limiting
$lockTable = "clinic_locks";

// Audit table structure (assuming clinic_id, user_id, action, timestamp)
$auditSql = "CREATE TABLE IF NOT EXISTS audit (
    id INT AUTO_INCREMENT PRIMARY KEY,
    clinic_id INT,
    user_id INT,
    action VARCHAR(255),
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
)";
$db->exec($auditSql);

// Function to update clinic status and handle all constraints
function updateClinicStatus($clinicId, $newStatus) {
    // Validate clinic ID and get the current status for logging purposes
    $sql = "SELECT id, status FROM clinics WHERE id = ?";
    $stmt = $db->prepare($sql);
    $stmt->execute([$clinicId]);
    $clinic = $stmt->fetch(PDO::FETCH_ASSOC);

    if (!$clinic) {
        logOperation("error", $_SERVER["REMOTE_USER"], $clinicId, "Invalid clinic ID");
        return ["status" => false, "message" => "Invalid clinic ID"];
    }

    // Start a new transaction
    try {
        $db->beginTransaction();

        // Acquire a lock to enforce rate limiting
        $lockSql = "INSERT INTO $lockTable (clinic_id) VALUES (?) ON DUPLICATE KEY UPDATE last_updated = NOW()";
        $stmt = $db->prepare($lockSql);
        $success = $stmt->execute([$clinicId]);

        if (!$success) {
            logOperation("error", $_SERVER["REMOTE_USER"], $clinicId, "Failed to acquire lock");
            $db->rollback(); // Rollback the transaction in case of failure
            return ["status" => false, "message" => "Failed to acquire lock"];
        }

        // Check if the lock expired (older than 1 minute)
        $lockSql = "SELECT last_updated FROM $lockTable WHERE clinic_id = ?";
        $stmt = $db->prepare($lockSql);
        $stmt->execute([$clinicId]);
        $lock = $stmt->fetch(PDO::FETCH_ASSOC);

        if (strtotime("now") - strtotime($lock["last_updated"]) > 60) { // More than 1 minute has passed since the last lock update
            logOperation("error", $_SERVER["REMOTE_USER"], $clinicId, "Lock expired");
            $db->rollback(); // Rollback the transaction in case of failure
            return ["status" => false, "message" => "Lock expired"];
        }

        // Update the clinic status
        $sql = "UPDATE clinics SET status = ? WHERE id = ?";
        $stmt = $db->prepare($sql);
        $success = $stmt->execute([$newStatus, $clinicId]);

        if (!$success) {
            logOperation("error", $_SERVER["REMOTE_USER"], $clinicId, "Failed to update clinic status");
            $db->rollback(); // Rollback the transaction in case of failure
            return ["status" => false, "message" => "Failed to update clinic status"];
        }

        // Log the operation
        logOperation("info", $_SERVER["REMOTE_USER"], $clinicId, json_encode(["action" => "update_status", "old_status" => $clinic["status"], "new_status" => $newStatus]));

        // Commit the transaction and send a notification to the external API
        $db->commit();
        notifyExternalApi($clinicId, $newStatus);

        // Return success response
        return ["status" => true];
    } catch (\Exception $e) {
        logOperation("error", $_SERVER["REMOTE_USER"], $clinicId, "Database error: " . $e->getMessage());
        return ["status" => false, "message" => "Database error: " . $e->getMessage()];
    }
}

// Function to log an operation in the audit table
function logOperation($level, $user, $clinicId, $data) {
    // Assuming you have a function getUserID() that returns the current user ID
    $userId = getUserID();

    $sql = "INSERT INTO audit (clinic_id, user_id, action, timestamp) VALUES (?, ?, ?, NOW())";
    $stmt = $db->prepare($sql);
    $success = $stmt->execute([$clinicId, $userId, $data]);
}

// Function to send a notification to the external API
function notifyExternalApi($clinicId, $newStatus) {
    // Assuming you have a function getExternalApiClient() that returns an instance of GuzzleHttp\Client or similar HTTP client library
    $client = getExternalApiClient();

