["```cpp
#include <iostream>
#include <openssl/sha.h>
#include <string>

std::string calculateMD5Hash(const std::string& input) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, input.c_str(), input.length());
    SHA256_Final(digest, &ctx);

    std::string result;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        std::stringstream ss;
        ss << std::hex << static_cast<unsigned int>(static_cast<unsigned char>(digest[i]));
        size_t len = ss.str().length();
        if (len < 2) ss << '0';
        result += ss.str();
    }

    return result;
}
```

