2. Implement the `DynamicScriptLoader` core functionality in `src/dynamicScriptLoader/index.js`.

```javascript
import { readDirectory, loadModule } from './utils';
import config from './config';
import logger from './logger';
import criticalScripts from './criticalScripts';

class DynamicScriptLoader {
  constructor() {
    this.scripts = [];
    this.executedCriticalScripts = 0;
    this.maxRetries = config.maxRetries;
  }

  loadScripts(directory) {
    return readDirectory(directory).then((files) => {
      files.forEach((file) => {
        if (/\.js$/.test(file)) {
          this.scripts.push(`${directory}/${file}`);
        }
      });
      this.executeScripts();
    });
  }

  executeScripts() {
    const scriptToExecute = this.getNextScript();
    if (scriptToExecute) {
      loadModule(scriptToExecute)
        .then(() => {
          this.executeCriticalOrNonCritical(scriptToExecute);
        })
        .catch((error) => {
          if (this.shouldRetry(error)) {
            this.retryScriptExecution(scriptToExecute);
          } else {
            logger.logError(`Failed to execute script "${scriptToExecute}": ${error}`);
          }
        });
    }
  }

  getNextScript() {
    return this.scripts.find((script) => {
      return (
        !this.executedCriticalScripts ||
        criticalScripts.includes(script) ||
        this.isNonCriticalScriptAllowedToRun()
      );
    });
  }

  executeCriticalOrNonCritical(script) {
    if (criticalScripts.includes(script)) {
      this.executedCriticalScripts++;
    }

    // Add your logic for executing the script here, e.g., calling an exported function from the loaded module.
  }

  isNonCriticalScriptAllowedToRun() {
    // Implement a logic to check system resource usage (e.g., memory and CPU load) and determine if non-critical scripts can be executed.
  }

  shouldRetry(error) {
    return error.name === 'Error' && this.remainingRetries() > 0;
  }

  remainingRetries() {
    return this.maxRetries - this.executedRetries();
  }

  executedRetries() {
    // Implement a logic to track the number of retries for each script and return it.
  }

  retryScriptExecution(script) {
    logger.logInfo(`Retrying failed script "${script}".`);
    this.scripts = this.scripts.filter((currentScript) => currentScript !== script);
    this.executeScripts();
  }
}
```

