#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long value;
} Record;

void init_dataset(Record** dataset, size_t capacity, int minValue, int maxValue) {
    if (capacity <= 0 || maxValue < minValue) {
        fprintf(stderr, "Invalid range or negative capacity.\n");
        return;
    }

    *dataset = malloc(capacity * sizeof(Record));
    if (!*dataset) {
        perror("Memory allocation failure.");
        return;
    }

    for (size_t i = 0; i < capacity; ++i) {
        (*dataset)[i].key = rand() % (maxValue - minValue + 1) + minValue;
        (*dataset)[i].value = rand() * RAND_MAX; // Make sure the value is within the maximum integer value of long data type.
    }
}
