int init_and_send_indications(void) {
    // Initialize list and populate with data
    // ...

    pthread_t threads[MAX_THREADS];
    int num_threads = 0;

    for (size_t i = 0; i < MAX_NUM_INDICATIONS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Set indication data here

        if (pthread_create(&threads[num_threads++], NULL, send_indication, indication)) {
            break;
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return num_threads == MAX_NUM_INDICATIONS;
}

void* send_indication(void* data) {
    NFAPI_CRC_INDICATION_PDU_T *indication = (NFAPI_CRC_INDICATION_PDU_T*)data;

    SSL_CTX* ctx = ssl_init();
    int sockfd = connect_to_service(ctx);
    if (sockfd == -1) {
        // Handle error and log
        free(indication);
        return 0;
    }

    send_pdu(sockfd, indication);
    close(sockfd);
    ssl_cleanup(ctx);

    free(indication);
    return 1;
}
