  2. **Java Utility (CSVProcessor.java)**

```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class CSVProcessor {
    private static final int PARALLELISM = Runtime.getRuntime().availableProcessors();

    public static void main(String[] args) throws Exception {
        List<Path> csvFiles = List.of(
                Path.of("path/to/file1.csv"),
                Path.of("path/to/file2.csv")
        );

        ExecutorService executor = Executors.newFixedThreadPool(PARALLELISM);
        List<Future<Map<String, Integer>>> futures = csvFiles.stream()
                .parallel()
                .map(CSVProcessor::processFile)
                .collect(Collectors.toList());

        for (Future<Map<String, Integer>> future : futures) {
            try {
                Map<String, Integer> result = future.get();
                // Process results here
            } catch (InterruptedException | ExecutionException e) {
                System.err.println("Error processing CSV: " + e.getMessage());
            }
        }

        executor.shutdown();
    }

    private static Callable<Map<String, Integer>> processFile(Path file) {
        return () -> {
            Map<String, Integer> result = Stream.of(new BufferedReader(new FileReader(file.toString())).lines()
                    .map(line -> line.split(","))
                    .filter(arr -> arr.length > 0)
                    .collect(Collectors.groupingBy(arr -> arr[0], Collectors.summingInt(arr -> Integer.parseInt(arr[1]))))
            ;
            return result;
        };
    }
}
```']

