// Image processing API client class
class ImageAPIClient {
public:
    virtual void processImage(const std::string& imageData, std::function<void()> callback) = 0;
};

// CachedImageAPIClient class inherits from ImageAPIClient and caches processed images using the specified cache system.
class CachedImageAPIClient : public ImageAPIClient {
public:
    explicit CachedImageAPIClient(const std::string& apiEndpoint, const std::string& cacheHost)
        : m_apiClient(std::make_unique<ImageAPIClient>()), m_cache(cacheHost) {}

    void processImage(const std::string& imageData, std::function<void()> callback) override {
        // Check if the image is already in cache before sending it to API
        auto it = m_cache.find(imageData);
        if (it != m_cache.end()) {
            callback();
            return;
        }

        // Send the image data to the external API for processing
        m_apiClient->processImage(std::move(imageData), [this, callback = std::move(callback)]() {
            if (m_cache.try_emplace(imageData).second) {
                m_cache[imageData] = true; // Mark the image as cached
                callback();
            } else {
                Log("Error caching image");
                callback();
            }
        });
    }

private:
    std::unique_ptr<ImageAPIClient> m_apiClient;
    boost::cache::cached_cow_map<std::string, bool> m_cache; // A cache for processed images
};

// ImageBatch class to manage a batch of images and process them in parallel using a specified number of threads.
class ImageBatch {
public:
    explicit ImageBatch(int threadCount, const std::vector<std::string>& imageData, void (*logger)(const char* message))
        : m_apiClient(new CachedImageAPIClient("apiEndpoint", "cacheHost")), m_threadCount(threadCount) {
        m_imageQueue.reserve(imageData.size());
        for (auto& image : imageData)
            m_imageQueue.emplace_back(std::move(image));
        startThreads();
    }

    ~ImageBatch() {
        m_shouldStop = true;
        m_condition.notify_all();
        for (auto& thread : m_threads)
            thread.join();
    }

private:
    void processImage(const std::string& imageData, int index, void (*logger)(const char* message)) {
        // Perform image processing using the specified API client and log errors
        try {
            m_apiClient->processImage(std::move(imageData), [this, index, logger](...) {});
        } catch (const std::exception& e) {
            logger("[Error] Image %d: %s", index, e.what());
        }
    }

    void worker() {
        while (!m_shouldStop) {
            std::unique_lock<std::mutex> lock(m_mutex);
            m_condition.wait(lock, [this] { return !m_imageQueue.empty(); });
            int index = m_imageQueue.front().first;
            auto imageData = m_imageQueue.front().second;
            m_imageQueue.pop_front();
            lock.unlock();

            processImage(std::move(imageData), index, Log);
        }
    }

    void startThreads() {
        m_threads.reserve(m_threadCount);
        for (int i = 0; i < m_threadCount; ++i)
            m_threads.emplace_back(boost::thread(&ImageBatch::worker, this));
    }

private:
    std::unique_ptr<CachedImageAPIClient> m_apiClient;
    int m_threadCount;
    std::mutex m_mutex;
    std::condition_variable m_condition;
    std::queue<std::pair<int, std::string>> m_imageQueue; // A queue of images to process, indexed by the batch order
    std::vector<boost::thread> m_threads;
    bool m_shouldStop = false;
};

// processImageStream function implementation
std::future<void> processImageStream(const std::string& apiEndpoint, const std::string& cacheHost, int batchSize, void (*logger)(const char* message)) {
    auto batch = std::make_shared<ImageBatch>(std::thread::hardware_concurrency(), {}, logger);

    // Read image data from the stream and add them to batches for processing
    while (true) {
        std::string imageData;
        // Read imageData from the input stream...

        if (!imageData.empty()) {
            batch->m_imageQueue.emplace_back(std::make_pair(batch->m_imageQueue.size(), std::move(imageData)));

            if (batch->m_imageQueue.size() >= batchSize) {
                // Create a new ImageBatch for the current batch and clear the local buffer
                auto newBatch = std::make_shared<ImageBatch>(std::thread::hardware_concurrency(), {}, logger);
                newBatch->startThreads();

                // Swap the pointers to the batches and continue processing with the new one
                batch.swap(newBatch);
                batch->m_imageQueue.clear();
            }
        }
    }

    return std::async(std::launch::async, [batch]() { batch.reset(); }); // Ensure the ImageBatch is destroyed when its reference goes out of scope
