public class EventProcessor
{
    public XmlElement FindSingleElement(XmlDocument document, string xpathExpression)
    {
        if (document == null) throw new ArgumentNullException(nameof(document), "XML document cannot be null.");
        if (string.IsNullOrWhiteSpace(xpathExpression)) throw new ArgumentOutOfRangeException(nameof(xpathExpression), "XPath expression must not be empty or whitespace.");

        var nodes = document.SelectNodes(xpathExpression);
        if (nodes == null || nodes.Count < 1)
        {
            if (nodes.Count > 1) throw new InvalidOperationException($"Multiple elements found for XPath expression: {xpathExpression}.");
            throw new XmlException("No element found for the given XPath expression.");
        }

        return nodes[0];
    }
}
