                    _logger.LogError(ex, $"Failed to fetch data from third-party API: Retry {i + 1}");
                    await Task.Delay((i + 1) * exponentialBackoff, CancellationToken.None).ConfigureAwait(false);
                }
            }

            _logger.LogError("Maximum retries reached for fetching data from third-party API.");
            throw new Exception("Failed to fetch data after max retries");
