            var cacheKey = $"{commandText}-{parameters.Aggregate("", (current, param) => current + param.ParameterName)}";
            var queryResult = GetFromCache<IDataReader>(cacheKey);

            if (queryResult != null && DateTimeOffset.UtcNow < queryResult.ExpirationTime)
                return queryResult;

            // Anonymize sensitive data before caching query results

            if (config?.AnonymizeSensitiveData ?? false)
                commandText = DataProtection.Protect(commandText);

            var stopwatch = Stopwatch.StartNew();
            using var reader = await command.ExecuteReaderAsync();
            stopwatch.Stop();

            // Optimize slow queries by automatically detecting and recompiling inefficient SQL patterns

            if (stopwatch.Elapsed > TimeSpan.FromSeconds(config?.QueryTimeout ?? 5))
                CompileInefficientQueries(_mlModel, commandText);

            SetInCache(cacheKey, reader, TimeSpan.FromMinutes(config?.CacheDuration ?? 10));

