#include <atomic>
#include <thread>
#include <chrono>
#include <iostream>
#include <mutex>
#include <queue>

struct LogEntry {
    std::string timestamp;
    int attack;
};

class Logger {
public:
    void log(const LogEntry& entry) {
        if (!isLoggingEnabled()) return;

        std::lock_guard<std::mutex> lock(mtx);
        logQueue.push(entry);
        std::thread([this]() { writeToLogFile(logQueue.front()); logQueue.pop(); }).detach();
    }

private:
    bool isLoggingEnabled() const { return loggingEnabled; }

    void writeToLogFile(const LogEntry& entry) {
        std::cout << "Logged: " << entry.timestamp << ", Attack: " << entry.attack << std::endl;
    }

    static constexpr int MAX_RETRIES = 3;
    std::queue<LogEntry> logQueue;
    std::mutex mtx;
    bool loggingEnabled = true;
};

void selectAttack(Logger& logger, const std::atomic_int& cooldown) {
    std::uniform_int_distribution<> dist(0, 1);
    std::chrono::steady_clock::time_point lastLogTime = std::chrono::steady_clock::now();

    while (true) {
        int attack = dist(dist);
        if (cooldown.load() > 0 && (std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - lastLogTime).count() < cooldown.load())) {
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            continue;
        }

        logger.log({ std::to_string(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - std::chrono::system_clock::now()).count()), attack });
        cooldown.store(5);
    }
}
