import json
from abc import ABC, abstractmethod
from typing import Dict, Any

class LogParserBase(ABC):
    @abstractmethod
    def parse(self, data: str) -> Dict[str, Any]:
        pass

class JsonLogFactoryRegistry():
    def __init__(self):
        self.registry = {}

    def register(self, log_id: str, factory: type):
        self.registry[log_id] = factory

    def create(self, log_id: str, data: str) -> LogParserBase:
        if log_id not in self.registry:
            raise KeyError(f"Log ID '{log_id}' not found.")
        return self.registry[log_id](data)

class JsonLogFactory(LogParserBase):
    def __init__(self, **kwargs):
        self.kwargs = kwargs

    def parse(self, data: str) -> Dict[str, Any]:
        return json.loads(data)
