<?php

class ClinicStatusUpdater {
    private $pdo;
    private $redis;
    private $apiClient;

    public function __construct(PDO $pdo, Redis $redis, ApiClient $apiClient) {
        $this->pdo = $pdo;
        $this->redis = $redis;
        $this->apiClient = $apiClient;
    }

    public function updateClinicStatus($clinicId, $newStatus) {
        // Start a transaction
        $this->pdo->beginTransaction();

        try {
            // Validate and sanitize input
            if (!ctype_digit($clinicId)) {
                throw new Exception("Invalid clinic ID");
            }

            // Verify the clinic exists in the database
            $stmt = $this->pdo->prepare('SELECT id FROM clinics WHERE id = :clinicId');
            $stmt->execute([':clinicId' => $clinicId]);
            if (!$stmt->rowCount()) {
                throw new Exception("Clinic not found");
            }

            // Update the clinic status in the database (atomic transaction)
            $stmt = $this->pdo->prepare('UPDATE clinics SET operational_status = :newStatus WHERE id = :clinicId');
            $stmt->execute([':newStatus' => $newStatus, ':clinicId' => $clinicId]);

            // Log the operation
            $this->logOperation($clinicId, $newStatus);

            // Send notification to external API
            try {
                $this->apiClient->sendNotification($clinicId, $newStatus);
            } catch (Exception $e) {
                // Handle API errors with retry logic
                for ($i = 0; $i < 3; $i++) {
                    try {
                        $this->apiClient->sendNotification($clinicId, $newStatus);
                        break;
                    } catch (Exception $ex) {
                        if (!$this->shouldRetry($e)) {
                            throw $ex;
                        }
                    }
                }
            }

            // Commit the transaction
            $this->pdo->commit();

            return true;
        } catch (Exception $e) {
            // Rollback the transaction and log error details
            $this->pdo->rollBack();
            $this->logError($e);

            throw $e;
        }
    }

    private function shouldRetry(Exception $exception) {
        return $exception->getCode() === E_WARNING || $exception->getCode() === E_RECOVERABLE_ERROR;
    }

