        private async Task ExecuteWithRetryAsync(Func<SqlConnection, Task> action, SqlConnection connection, int maxAttempts)
        {
            int attempts = 0;
            while (attempts < maxAttempts)
            {
                try
                {
                    await action(connection);
                    return;
                }
                catch when (ex is SqlException) // Handle specific database exceptions as needed
                {
                    attempts++;
                    await Task.Delay(Math.Pow(2, attempts));
                }
            }

            Console.WriteLine($"Unable to connect after {maxAttempts} retries.");
            throw new ApplicationException("Database connection failed");
        }

