import java.util.concurrent.*;

public class CsvProcessor {
    private ExecutorService executor = Executors.newFixedThreadPool(10);

    public void processCsvFiles(List<String> filePaths, Runnable callback) throws IOException {
        List<Future<Void>> futures = new ArrayList<>();

        for (String filePath : filePaths) {
            Callable<Void> callable = () -> processCsvFile(filePath, callback);
            Future<Void> future = executor.submit(callable);
            futures.add(future);
        }

        for (Future<Void> future : futures) {
            try {
                future.get();
            } catch (ExecutionException | InterruptedException e) {
                System.out.println("Error processing file: " + e.getMessage());
            }
        }
    }

    private void processCsvFile(String filePath, Runnable callback) throws IOException {
        try (Reader reader = Files.newBufferedReader(Paths.get(filePath))) {
            CSVParser parser = new CSVParser(reader, CSVFormat.DEFAULT);
            Iterable<CSVRecord> records = parser;
            int recordNumber = 0;

            for (CSVRecord record : records) {
                processRecord(record, callback);
                recordNumber++;
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
        }
    }

    private void processRecord(CSVRecord record, Runnable callback) {
        try {
            // Process the record here, handle malformed data and missing fields gracefully
            callback.run();
        } catch (Exception e) {
            System.out.println("Error processing record: " + e.getMessage());
            // Logging and error handling strategy here
        }
    }
}
