using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using StackExchange.Redis;

public class FileStorageService : IFileStorageService
{
    private readonly ILogger<FileStorageService> _logger;
    private readonly IConfiguration _configuration;
    private readonly IDatabase _redisDatabase;
    private readonly int _retryAttempts;
    private readonly TimeSpan _retryInterval;

    public FileStorageService(ILogger<FileStorageService> logger, IConfiguration configuration, IOptionsMonitor<RedisCacheOptions> redisOptions, IHttpClientFactory httpClientFactory)
    {
        _logger = logger;
        _configuration = configuration;
        _redisDatabase = redisOptions.CurrentValue.ConnectionMultiplexer.GetDatabase();

        _retryAttempts = int.Parse(_configuration["FileStorage:RetryAttempts"]);
        _retryInterval = TimeSpan.FromSeconds(double.Parse(_configuration["FileStorage:RetryInterval"]));

        var httpClient = httpClientFactory.CreateClient("IndexingApi");
        _indexingApiClient = new HttpRequestMessageWrapper(httpClient, _logger);
    }

    private readonly HttpRequestMessageWrapper _indexingApiClient;

    public async Task<(byte[] FileData, IDictionary<string, string> Metadata)> UploadFileAsync(Stream fileStream, IDictionary<string, string> metadata)
    {
        var tempDirectory = GetTempDirectory();
        var temporaryFilePath = Path.Combine(tempDirectory, Guid.NewGuid().ToString() + Path.GetExtension(fileStream.Name));

        await using (var tempFileStream = File.OpenWrite(temporaryFilePath))
        {
            await fileStream.CopyToAsync(tempFileStream);
        }

        var indexingResult = await IndexFileAsync(temporaryFilePath, metadata);

        // Store the metadata associated with the file in Redis for later retrieval
        _redisDatabase.HashTags.Add(indexingResult.IndexId, metadata.Keys.ToArray(), metadata.Values.ToArray());

        return (File.ReadAllBytes(temporaryFilePath), indexingResult.Metadata);
    }

    private string GetTempDirectory()
    {
        var baseDirectory = _configuration["FileStorage:BaseDirectory"];
        var tempDirectory = Path.Combine(baseDirectory, Guid.NewGuid().ToString());

        if (Directory.Exists(tempDirectory))
        {
            // Handle existing writable directory by selecting a new subdirectory or create a new directory
            return GetTempDirectory();
        }

        Directory.CreateDirectory(tempDirectory);
        _configuration["FileStorage:BaseDirectory"] = tempDirectory;

        return tempDirectory;
    }

    private async Task<(string IndexId, IDictionary<string, string> Metadata)> IndexFileAsync(string filePath, IDictionary<string, string> metadata)
    {
        const int maxAttempts = 5;
        int attempt = 0;

        var requestContent = new FormUrlEncodedContent(metadata);
        var indexingRequest = new HttpRequestMessage
        {
            Method = HttpMethod.Post,
            RequestUri = new Uri(_configuration["IndexingApi:BaseUrl"]),
            Content = requestContent
        };

        while (attempt < maxAttempts)
        {
            try
            {
                using var fileStream = File.OpenRead(filePath);
                indexingRequest.Headers.Add("X-File-Size", fileStream.Length.ToString());
                indexingRequest.Content = new StreamContent(fileStream);

                var response = await _indexingApiClient.SendAsync(indexingRequest, HttpCompletionOption.ResponseHeadersRead);
                response.EnsureSuccessStatusCode();

                // Parse the response and extract the IndexId from it
                var indexId = GetIndexIdFromResponse(response);
                var metadataFromResponse = GetMetadataFromResponse(response);

                return (indexId, metadataFromResponse);
            }
            catch (HttpRequestException ex) when (attempt < _retryAttempts)
            {
                _logger.LogError(ex, "Failed to index file; retrying in {Interval} seconds", _retryInterval.TotalSeconds);
                await Task.Delay(_retryInterval);
                attempt++;
            }
        }

        throw new Exception("Unable to index file after maximum retries");
    }

    // Add implementation for edge cases, error handling, and performance optimization
}
```']

