async fn get_secret() -> Result<Value, reqwest::Error> {
    // ... Implement request to the external configuration management service
}

static WORKSPACE_LOCK: Mutex<Option<File>> = Mutex::new(None);

fn initialize_unique_workspace() -> Result<PathBuf, Box<dyn std::error::Error> {
    let workspace_path = match get_secret().await?["workspace"].as_str() {
        Some(path) => PathBuf::from(path),
        None => FALLBACK_PATH.to_owned(),
    };

    // Obtain a lock before proceeding
    let mut lock = WORKSPACE_LOCK.lock().await;
    if let Some(ref mut file) = lock {
        if !file.is_open() {
            *file = File::create(LOCK_FILE)?;
        }
        return Err(Box::new(ResourceInUseError));
    } else {
        *lock = Some(File::create(LOCK_FILE)?);
    }

    let temp_dir = TempDir::new("workspace")?;
    let workspace_path = temp_dir.into_path();

    // Ensure the created directories are writable and remove any existing ones
    fs::create_dir_all(workspace_path.join(".cache"))?;
    fs::create_dir_all(workspace_path.join("logs"))?;

    let _ = env::set_current_dir(&workspace_path)?;

    // ... Implement caching, rate limiting, and cleanup logic here

    info!("Initialized unique workspace: {}", workspace_path.display());

    Ok(workspace_path)
}
