#include "third_party_CRC_lib.h"

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag; // randomly initialized to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct queue_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct queue_node *next;
} queue_node_t;

struct queue {
    pthread_mutex_t lock;
    queue_node_t *head, *tail;
};

void create_queue(struct queue *q) {
    q->head = NULL;
    q->tail = NULL;
    pthread_mutex_init(&q->lock, NULL);
}

void enqueue(struct queue *q, NFAPI_CRC_INDICATION_PDU_T data) {
    queue_node_t *new_node = malloc(sizeof(queue_node_t));

    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&q->lock);

    if (!q->head) {
        q->head = new_node;
        q->tail = new_node;
    } else {
        q->tail->next = new_node;
        q->tail = new_node;
    }

    pthread_mutex_unlock(&q->lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(struct queue *q) {
    NFAPI_CRC_INDICATION_PDU_T data;
    queue_node_t *temp;

    pthread_mutex_lock(&q->lock);

    if (q->head == NULL) {
        pthread_mutex_unlock(&q->lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0};
    }

    data = q->head->data;
    temp = q->head;
    q->head = q->head->next;

    if (q->head == NULL) {
        q->tail = NULL;
    }

    free(temp);
    pthread_mutex_unlock(&q->lock);

    return data;
}

void init_struct(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crcflag = (bool)(rand() % 2); // randomly initialize crcflag to 0 or 1
}

int process_PDUs(struct queue *queue, int num_workers) {
    pthread_t workers[num_workers];
    NFAPI_CRC_INDICATION_PDU_T pdu;

    for (int i = 0; i < num_workers; ++i) {
        pthread_create(&workers[i], NULL, process_worker, queue);
    }

    for (int i = 0; i < num_workers; ++i) {
        pthread_join(workers[i], NULL);
    }

    return 0;
}

void* process_worker(void *arg) {
    struct queue *queue = arg;

    while (true) {
        pdu = dequeue(queue);

        if (!pdu.crcflag) continue; // skip if CRC flag is 0

        if (third_party_CRC_validation(&pdu->crc_indication)) {
            // Handle valid CRC indications here
        } else {
            // Handle CRC validation errors here
        }
    }

    return NULL;
}
```

