// Custom memory allocator
typedef struct _mem_pool MemPool;
struct _mem_pool {
    void *buffer;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
};

MemPool* mem_pool_create(size_t size) {
    MemPool *pool = malloc(sizeof(MemPool));
    if (!pool) return NULL;

    pool->buffer = malloc(size);
    if (!pool->buffer) goto error;

    pool->capacity = size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
error:
    free(pool);
    return NULL;
}

void* mem_pool_alloc(MemPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->used + size > pool->capacity) goto error;

    void *memory = pool->buffer + pool->used;
    pool->used += size;

    pthread_mutex_unlock(&pool->lock);
    return memory;
error:
    pthread_mutex_unlock(&pool->lock);
    log_error("Memory allocation failed");
    return NULL;
}

void mem_pool_free(MemPool *pool, void *memory) {
    if (!pool || !memory) return;

    pthread_mutex_lock(&pool->lock);

    pool->used -= memory - pool->buffer;
    pthread_mutex_unlock(&pool->lock);
}

