// RAII for memory management
template<typename T>
class ScopedVector {
public:
    explicit ScopedVector(std::vector<T>* vec) : _vec(vec) {}
    ~ScopedVector() { _vec->clear(); delete _vec; }

    std::vector<T>& get() { return *_vec; }

private:
    std::vector<T>* _vec;
