// CRC_INDICATION_PDU_T structure
struct CRCAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
};

// Thread-safe random number generator
std::mt19937_64 prng;

void init_random(unsigned long seed) {
    std::random_device rd;
    if (seed) prng.seed(seed);
    else prng.seed(rd());
}

// Generate random CRCFLAG value
bool generate_crcflag() { return (prng() >> 64) % 2 == 0 ? true : false; }

// Function to generate and persist N structures
ScopedVector<CRCAPI_CRC_INDICATION_PDU_T> generate_structures(int N, DBConnection& dbconn) {
    ScopedVector<CRCAPI_CRC_INDICATION_PDU_T> pdu_list(new std::vector<CRCAPI_CRC_INDICATION_PDU_T>());

    // Generate and populate structures
    for (int i = 0; i < N; ++i) {
        CRCAPI_CRC_INDICATION_PDU_T pdu;
        pdu.tag.setValue(i);
        pdu.rnti = rand() % UINT32_MAX;
        pdu.crc_indication_tag.setCrcfalg(generate_crcflag());
        pdu_list->push_back(pdu);
    }

    // Persist the generated structures in the database
    auto txn = dbconn.get().beginTransaction();
    for (const auto& pdu : *pdu_list) {
        try {
            // Insert the PDU into the database
            txn->exec("INSERT INTO crc_indications VALUES($1, $2, $3)", pdu.tag.getValue(), pdu.rnti,
                      (int)(pdu.crc_indication_tag.getCrcfalg() ? 1 : 0));
        } catch (const std::exception& e) {
            txn->rollback();
            // Log the error and implement retry logic or fallback strategies
        }
    }
    txn->commit();

    return pdu_list;
}

// Main function
int main(int argc, char* argv[]) {
    int N = 10;  // Number of structures to generate
    unsigned long seed = 0;  // Randomness seed

    if (argc > 1) N = std::stoi(argv[1]);
