    (elapsed, memory)
}

// Utilize `SyncLazy` module to install an ice hook and catch errors during compilation
use std::sync::atomic::{AtomicUsize, Ordering};
static NUM_COMPILATION_ERRORS: AtomicUsize = AtomicUsize::new(0);

#[global_allocator]
static GLOBAL: JemallocAllocator = JemallocAllocator {};

// Register the ice hook and report errors with `early_error` function
#[no_mangle]
pub extern "C" fn rustc_after_config(_argc: usize, _argv: *const *const u8) -> ! {
    if NUM_COMPILATION_ERRORS.load(Ordering::SeqCst) > 0 {
        early_error!("Compilation errors detected!");
    }
    std::panic::unwind_scope::<()>().unwrap_or_else(|err| {
        if let Some(source) = err.source() {
            let (elapsed, memory) = measure_compiler_perf(&source);
            early_error!(
                "Compilation error occurred: {} ({:?} seconds, {:?} bytes)",
                source, elapsed, memory
            );
        } else {
            early_error!("Unexpected panic during compilation!");
        }
    })
}
