<?php
function updateClinicStatus($clinicId, $status, $userId) {
    $db = new PDO('mysql:host=localhost;dbname=myDatabase', 'username', 'password');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    // Begin transaction
    $db->beginTransaction();

    try {
        // Validate clinic ID exists and input sanitize/validate using proper libraries
        $stmt = $db->prepare("SELECT id FROM clinics WHERE id = ?");
        $stmt->execute([$clinicId]);
        if ($stmt->rowCount() === 0) {
            throw new Exception("Invalid clinic ID.");
        }

        // Lock record to prevent simultaneous updates
        $lockKey = md5($clinicId . time());
        $stmt = $db->prepare("UPDATE clinics SET lock_key = ? WHERE id = ? FOR UPDATE SKIP LOCKED");
        $stmt->execute([$lockKey, $clinicId]);

        // Perform update and log details
        $now = new DateTimeImmutable();
        $stmt = $db->prepare("UPDATE clinics SET operational_status = ?, updated_at = ? WHERE id = ?");
        $stmt->execute([$status, $now->format('Y-m-d H:i:s'), $clinicId]);

        // Log operation details (assuming you have a log table with columns like log_id, clinic_id, user_id, timestamp, action, error)
        $stmt = $db->prepare("INSERT INTO logs (clinic_id, user_id, timestamp, action, error) VALUES (?, ?, ?, ?, ?)");
        $stmt->execute([$clinicId, $userId, $now, "Update status", ""]);

        // Integrate with external API
        $apiResult = callExternalApi($status);

        // Commit transaction and release lock
        $db->commit();
        $stmt = $db->prepare("UPDATE clinics SET lock_key = NULL WHERE id = ?");
        $stmt->execute([$clinicId]);

        return $apiResult;
    } catch (\Exception $e) {
        // Rollback transaction and log error details
        $db->rollBack();
        // Log the error (including stack trace, user ID, clinic ID, timestamp)
        $stmt = $db->prepare("INSERT INTO logs (clinic_id, user_id, timestamp, action, error) VALUES (?, ?, ?, ?, ?)");
