```javascript
const fs = require('fs');
const path = require('path');
const readline = require('readline');
const async = require('async');
const limiter = require('limiter');
const axios = require('axios');
const moment = require('moment');
const config = require('./config'); // Configuration file

// Define filter criteria
function isRelevantLog(entry) {
  const now = moment();
  return entry.timestamp <= now && (entry.errorCode === config.ERROR_CODE || !config.ERROR_CODE);
}

// Create a rate limiter for external API calls
const apiLimiter = limiter(config.API_RATE_LIMIT);

function readFileAsync(filePath) {
  return new Promise((resolve, reject) => {
    const rl = readline.createInterface({
      input: fs.createReadStream(filePath),
    });

    const logs = [];

    rl.on('line', (line) => {
      let logEntry = JSON.parse(line); // Assuming logs are in JSON format
      if (isRelevantLog(logEntry)) logs.push(logEntry);
    });

    rl.on('close', () => resolve(logs));
  });
}

function processLogEntry(entry) {
  return apiLimiter(() => axios.get(`${config.API_URL}/lookup`, { params: entry })
    .then(({ data }) => ({ ...entry, metadata: data }))
    .catch((err) => {
      console.error(`Error processing log entry: ${JSON.stringify(entry)}`, err);
      return entry; // Retry mechanism - if error, just move on to the next one
    }));
}

async function processDirectory(directoryPath) {
  const files = await fs.promises.readdir(directoryPath);

  async.eachSeries(files, async (file, callback) => {
    const filePath = path.join(directoryPath, file);
    try {
      if (fs.statSync(filePath).isDirectory()) return processDirectory(filePath); // Recursive processing for directories

      const logs = await readFileAsync(filePath);
      const processedLogs = await async.mapSeries(logs, processLogEntry);
      // Process and aggregate data based on the use-case here...
    } catch (err) {
      console.error(`Error processing file ${filePath}:`, err);
      callback(err);
    }
  }, () => {});
}

processDirectory(config.DIRECTORY_PATH) // Start the service
```

This example demonstrates a modular design, intelligent concurrency control using async series and mapSeries functions, and efficient error handling with Promises. Testing strategies can be implemented using libraries like Mocha or Jest to cover edge cases. You may want to consider further optimizations based on the specifics of your project requirements."]

