class TestRunner {
  constructor() {
    this.testModules = new Map();
    this.mockRegistry = new Map();
    this.cache = cache({ max: 1000 });
  }

  loadTestModule(modulePath) {
    if (!this.testModules.has(modulePath)) {
      const module = this.cache.get(modulePath);
      if (module) return module;

      try {
        module = await import(modulePath);
        this.testModules.set(modulePath, module);
        this.cache.set(modulePath, module);
