            .post("http://example.com/api")
            .header("Content-Type", "application/octet-stream")
            .body(self.serialize().await)
            .send()
            .await
        {
            Ok(res) => res,
            Err(e) => {
                eprintln!("Error sending data to server: {}", e);
                return;
            }
        };

        if let Err(e) = response.error_for_status() {
            eprintln!("Error from server: {}", e);
        } else if let Some(res) = response.ok() {
            println!("Response received: {}", res.text().await?.trim());
        }
    }
}

async fn populate_pdu_list(rng: &mut impl Rng, num_pdus: usize) -> PduList {
    let mut pdu_list = PduList { data: LinkedList::new() };

    for _ in 0..num_pdus {
        let rnti = rng.gen::<u32>();
        let crcflag = rng.gen::<bool>();

