2. Performance measurement function:
```rust
use std::env;
use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::process::Command;
use std::time::Instant;
use std::os::unix::process::ExitStatusExt;

fn measure_compile_time(source_file: &str) {
    let start = Instant::now();
    let output = Command::new("rustc")
        .arg(source_file)
        .output()
        .expect("failed to execute process");

    if !output.status.success() {
        println!("compile failed: {}", String::from_utf8_lossy(&output.stderr));
        return;
    }

    let elapsed = start.elapsed().as_secs_f64();
    let mem_use = get_resident_set_size() / 1_000_000 as f64;
    println!("compile time: {}s, memory usage: {}", elapsed, mem_use);
}

fn get_resident_set_size() -> u64 {
    let mut file = File::open("/proc/self/stat").expect("failed to open file");
    let mut buf = [0; 256];
    match file.read_exact(&mut buf) {
        Ok(_) => {
            let pid = buffer_to_pid(&buf);
            unsafe { libc::syscall(libc::SYS_getrusage, pid as i32, 0 as *const libc::c_ulong as _, buf.as_mut_ptr() as *mut libc::rusage) };
            let rss = buf[64] | (buf[65] as u64) << 8;
            rss
        }
        Err(e) => {
            eprintln!("failed to read /proc/self/stat: {}", e);
            0
        }
    }
}
```

