```rust
use std::sync::{Lazy, RwLock};
use std::cell::RefMut;
use std::fmt;
use std::panic;
use std::thread::panicking;

struct EarlyError {
    error: Option<Box<dyn fmt::Display + Send>>,
}

impl EarlyError {
    fn new() -> Self {
        EarlyError { error: None }
    }

    fn set(&mut self, error: Box<dyn fmt::Display + Send>) {
        self.error = Some(error);
    }
}

static EARLY_ERROR: Lazy<RefMut<EarlyError>> = SyncLazy::new(|| RwLock::new(EarlyError::new()));

unsafe fn early_error() {
    if let Some(ref mut error) = *EARLY_ERROR.write().unwrap().error.as_mut() {
        panic!("{}", error);
    }
}
```

