```c
#include <jansson/jansson.h>
#include <stdio.h>
#include <string.h>

bool validate_oauth2_access_token(const char *json_str) {
    json_t *root, *scope, *expires_in;
    const char *err = NULL;

    root = json_loads(json_str, 0, &err);
    if (!root || err) {
        printf("Error parsing JSON: %s\n", err);
        return false;
    }

    scope = json_object_get(root, "scope");
    expires_in = json_object_get(root, "expires_in");

    if (!json_is_string(scope) || !json_is_integer(expires_in)) {
        printf("JSON fields 'scope' and 'expires_in' are not in the expected format.\n");
        return false;
    }

    json_decref(root);
    return true;
}
