use std::env;
use std::fs::create_dir_all;
use std::io::{BufWriter, Write};
use std::path::PathBuf;

pub fn create_directory_and_set_env(dirname: &str) -> Result<(), Box<dyn std::error::Error>> {
    let dir = PathBuf::from(dirname);
    if env::var("MY_DIR").is_ok() {
        let path = env::var("MY_DIR")?;
        if dir.eq_path(&PathBuf::from(path)) {
            return Ok(());
        }
    }

    create_dir_all(&dir)?;
    let path = dir.to_str().unwrap();
