const fs = require('fs');
const path = require('path');
const OrderedAsyncPromises = require('ordered-async-promises');

class FileLoader {
  constructor(files) {
    this.files = files;
  }

  load() {
    return new OrderedAsyncPromises((resolve, reject) => {
      let loadedFiles = [];
      const loadFile = (filePath) => {
        fs.readFile(filePath, 'utf8', (err, data) => {
          if (err) {
            // Handle errors here, e.g., log, retry, or skip the file based on your requirements.
          } else {
            loadedFiles.push({path: filePath, data: data});
            if (loadedFiles.length === this.files.length) {
              resolve(loadedFiles);
            }
          }
        });
      };

      for (let file of this.files) {
        const filePath = path.resolve(__dirname, file);
        loadFile(filePath);
      }
    });
  }

  execute(callback) {
    return this.load().then((loadedFiles) => {
      // Execute the loaded files in order and pass their results to the callback function.
