        var deferred = $q.defer();

        if (!activeRequests[resourceId]) {
            activeRequests[resourceId] = true;
            $timeout(function() {
                angular.forEach(apiEndpoints, function(endpoint) {
                    if (endpoint.fields.indexOf(resourceId) !== -1) {
                        $http.get(endpoint.url).then(function(response) {
                            var data = response.data;

                            angular.forEach(fields, function(fieldName) {
                                if (fieldSchemas[fieldName]) {
