import threading

class TokenLock:
    def __init__(self):
        self.lock = threading.RLock()

    def acquire(self, token):
        with self.lock:
            self._tokens[token] = True

    def release(self, token):
        with self.lock:
            if token in self._tokens:
                del self._tokens[token]
```

