import random
from time import sleep

class RetryStrategy:
    def __init__(self):
        self.backoff = exponential_backoff()
        self.jitter = jitter(self.backoff)

    def retry(self, func, args=None, kwargs=None, max_retries=3):
        retries = 0
        while True:
            try:
                return func(*args, **kwargs)
            except exceptions.APIError as e:
                if retries >= max_retries:
                    raise e
                sleep(self.backoff() + self.jitter())
                retries += 1
```

