class MemoryPoolManager {
private:
    std::vector<void*> freeBlock;
    std::vector<void*> allocatedBlock;
    size_t blockSize;
public:
    MemoryPoolManager(size_t blockSize) : blockSize(blockSize) {}

    void* allocate() {
        if (!freeBlock.empty()) {
            auto result = freeBlock.back();
            freeBlock.pop_back();
            allocatedBlock.push_back(result);
            return result;
        }
        void* result = operator new(blockSize);
        return result;
    }

    void deallocate(void* ptr) {
        if (std::find(allocatedBlock.begin(), allocatedBlock.end(), ptr) != allocatedBlock.end()) {
            allocatedBlock.erase(std::find(allocatedBlock.begin(), allocatedBlock.end(), ptr));
            freeBlock.push_back(ptr);
        }
    }
};

