2. OAuth2 Access Token Validation Function in C:

```c
#include <jansson.h>
#include <stdio.h>

bool validate_oauth2_token(char *json_str) {
    json_t *root, *access_token, *expires_in, *token_type;
    int expires_in_int;

    root = json_loads(json_str, 0, NULL);

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");

    if (!json_is_string(access_token) || !json_is_integer(expires_in) || !json_is_string(token_type)) {
        return false;
    }

    if (strcmp(json_string_value(token_type), "Bearer") != 0 || json_integer_value(expires_in) <= 0) {
        return false;
    }

    expires_in_int = json_integer_value(expires_in);
    if (expires_in_int < time(NULL)) {
        return false;
    }

    return true;
}
```

