static CPU_USAGE_METRIC: LazyLock<u64> = SyncLazy::new(|| {
    let mut output = String::new();
    Command::new("top")
        .arg("-bn1")
        .output()
        .expect("failed to execute process")
        .stdout_mut(&mut output);
    output.trim().split('\n')
