    public class WebsiteDeploymentService : IWebsiteDeploymentService
    {
        private readonly ILogger<WebsiteDeploymentService> _logger;
        private readonly IWebHostEnvironment _environment;
        private readonly DeploymentValidator _deploymentValidator;
        private readonly int _maxAllowedDirectorySizeInCharacters;

        public WebsiteDeploymentService(ILogger<WebsiteDeploymentService> logger,
                                         IWebHostEnvironment environment,
                                         DeploymentValidator deploymentValidator,
                                         IConfiguration configuration)
        {
            _logger = logger;
            _environment = environment;
            _deploymentValidator = deploymentValidator;
            _maxAllowedDirectorySizeInCharacters = configuration["MaxAllowedDirectorySize"].GetValue<int>();
        }

        public async Task<DeploymentResult> CreateWebsiteInstanceAsync(string directoryPath, string siteName)
        {
            if (string.IsNullOrWhiteSpace(directoryPath))
                throw new ArgumentNullException(nameof(directoryPath));

            var sanitizedDirectoryPath = SanitizeDirectoryPath(directoryPath);
            if (!File.Exists($"{sanitizedDirectoryPath}/web.config"))
            {
                _logger.LogError("Invalid web application directory provided.");
                return new DeploymentResult { Success = false, ErrorMessage = "Invalid web application directory provided." };
            }

            if (_deploymentValidator.ValidateDirectory(sanitizedDirectoryPath, _maxAllowedDirectorySizeInCharacters))
            {
                await CreateWebsiteInstanceInternalAsync(sanitizedDirectoryPath, siteName);
            }

            return new DeploymentResult { Success = true };
        }

        private string SanitizeDirectoryPath(string directoryPath) => directoryPath.Trim().Replace(" ", "_");

        private async Task CreateWebsiteInstanceInternalAsync(string sanitizedDirectoryPath, string siteName)
        {
            var cancellationTokenSource = new CancellationTokenSource();

            // Parallelize the creation process to support high-load scenarios
            var tasks = Enumerable.Range(0, 10)
                .Select(_ => Task.Run(() => PerformDeploymentTaskAsync(sanitizedDirectoryPath, siteName, cancellationTokenSource.Token)));

            await Task.WhenAll(tasks);

            cancellationTokenSource.Dispose();
        }

        private void PerformDeploymentTaskAsync(string sanitizedDirectoryPath, string siteName, CancellationToken token)
        {
            try
            {
                // Implement the actual deployment logic here
                _logger.LogInformation($"Deploying website '{siteName}' from directory '{sanitizedDirectoryPath}'.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"An error occurred during the deployment of website '{siteName}'.");
            }
        }
    }
}
```

