    @lru_cache(maxsize=128)  # Cache configuration data to minimize latency
    async def get_config(self):
        config = await self.resolver.resolve(await self.fetch_config())
        return config

    async def fetch_config(self):
        configs = [source.get() for source in self.sources]
        return self.combine_configs(configs)

    def combine_configs(self, configs: List[Dict]):
