namespace ImageProcessing {

class Task {
public:
    virtual void apply(std::istream& input, std::ostream& output) const = 0;
    virtual std::string name() const = 0;
    virtual ~Task() {}
};

template <typename Derived>
class TaskTemplate : public Task {
public:
    TaskTemplate() : m_name(Derived::taskName()) {}

    void apply(std::istream& input, std::ostream& output) const override {
        static_cast<const Derived*>(this)->apply(input, output);
    }

    std::string name() const override {
        return m_name;
    }

private:
    const std::string m_name;
};

class TaskRegistry {
public:
    void registerTask(const std::string& name, std::unique_ptr<Task> task) {
        std::lock_guard<std::mutex> lock(m_tasksMutex);
        m_tasks[name] = std::move(task);
    }

    const Task* getTask(const std::string& name) const {
        std::lock_guard<std::mutex> lock(m_tasksMutex);
        auto it = m_tasks.find(name);
        return it != m_tasks.end() ? it->second.get() : nullptr;
    }

private:
    std::map<std::string, std::unique_ptr<Task>> m_tasks;
    mutable std::mutex m_tasksMutex;
};

