static TIMER: Lazy<Mutex<Option<Instant>>> = Lazy::new(|| Mutex::new(None));

fn start_timer() {
    *TIMER.lock().unwrap() = Some(Instant::now())
}

fn stop_timer() {
    let now = Instant::now();
    let elapsed = now - TIMER.lock().unwrap().take().unwrap();
    println!("Elapsed time: {}", elapsed.as_secs_f64());
}
```

