class MemoryPool {
public:
    // Function to allocate memory from the pool
    std::unique_ptr<Node> Allocate() {
        if (!freeNodes.empty()) {
            auto node = freeNodes.back();
            freeNodes.pop_back();
            return std::move(node);
        }
        return std::make_unique<Node>();
    }

    // Function to free memory back into the pool
    void Free(std::unique_ptr<Node> node) {
        if (!freeNodes.empty()) {
            // Handle potential issues with different pointer types
            dynamic_cast<Node*>(node.get())->~Node();
            freeNodes.push_back(std::move(node));
