    public abstract class DataProcessor<T> where T : class
    {
        protected readonly IDataProvider dataProvider;
        protected readonly IMessageBroker messageBroker;
        protected readonly IDistributedStore distributedStore;

        protected DataProcessor(IDataProvider dataProvider, IMessageBroker messageBroker, IDistributedStore distributedStore)
        {
            this.dataProvider = dataProvider;
            this.messageBroker = messageBroker;
            this.distributedStore = distributedStore;
        }

        public virtual async Task ProcessDataAsync(T data)
        {
