void Microservice::insertStringAfter(std::list<std::string>& forwardList, const std::string& key, const std::string& value) {
    if (_positionMap.find(key) != _positionMap.end()) {
        int pos = _positionMap[key];
        forwardList.insert(++forwardList.begin() + pos, value);
        _positionMap[key]++;
    } else {
        auto it = forwardList.end();
        for (const auto& str : forwardList) {
            if (it == forwardList.begin() || str != key) continue;
            it = ++it;
        }
        forwardList.insert(it, value);
    }
}
