use std::time::{Instant, Duration};
use std::process;
use std::os::unix::process::CommandExt;
use std::ffi::OsString;
use std::iter::once;

fn measure_compiler_performance(source: &str) {
    let cmd = format!(
        "rustc -C debuginfo=2 -C opt-level={} {}",
        OPTIMIZATION_LEVEL, source
    );
    let mut process = Command::new("rustc");
    process.arg(source);
    process.args(&["--"]);
    let start = Instant::now();
    let output = process.output().expect("Failed to execute command");
    let duration = start.elapsed();
    let memory_usage = get_resident_set_size() - initial_memory_usage;

    if !output.status.success() {
        early_error!(format!("Rust compiler failed with exit code {}: {}", output.status().code(), String::from_utf8_lossy(&output.stderr)));
    }

    println!("Time taken: {} seconds", duration.as_secs_f64());
