using StackExchange.Redis;

namespace WebsiteDeploymentService
{
    public class WebsiteDeploymentService
    {
        private readonly IConfiguration _config;
        private readonly ILogger<WebsiteDeploymentService> _logger;
        private readonly IDatabase _redisDatabase;
        private readonly ConcurrentDictionary<string, Task<bool>> _deploymentsInProgress;

        public WebsiteDeploymentService(IConfiguration config, ILogger<WebsiteDeploymentService> logger, IConnectionMultiplexer redis)
        {
            _config = config;
            _logger = logger;
            _redisDatabase = redis.GetDatabase();
            _deploymentsInProgress = new ConcurrentDictionary<string, Task<bool>>();
        }

        public async Task<string> DeployWebsiteAsync(string directoryPath, string siteName, int maxDirectoryLength, IConfiguration configuration)
        {
            if (directoryPath.Length > maxDirectoryLength || !Directory.Exists(SanitizeDirectoryPath(directoryPath)) || !File.Exists(GetValidConfigFilePath(directoryPath)))
            {
                _logger.LogError("Invalid directory path or missing web.config file.");
                return "Invalid deployment request.";
            }

            // Add to redis set for concurrency control and remove after completion
            string lockKey = $"deployment-lock:{siteName}";
            if (_redisDatabase.SetAdd(lockKey, true).Result != 1)
            {
                _logger.LogWarning($"Attempt to deploy site '{siteName}' was denied due to concurrency restrictions.");
                return "Deployment concurrency restricted.";
            }

            var deploymentTask = DeployWebsiteInternal(directoryPath, siteName, configuration);
            _deploymentsInProgress.TryAdd(lockKey, deploymentTask);

            await deploymentTask;

            if (deploymentTask.Result)
            {
                // Remove from redis set after successful completion
                _redisDatabase.SetRemove(lockKey);

                return "Deployment successful.";
            }
            else
            {
                _logger.LogError($"Failed to deploy site '{siteName}'. Rolling back.");
                // Implement rollback logic here

                return "Deployment failed.";
            }
        }

        private string GetValidConfigFilePath(string directoryPath) => Path.Combine(directoryPath, "web.config");

        private static string SanitizeDirectoryPath(string path) => path.Trim().Replace("\\", "_").Replace("/", "_");
    }
}
```

