TEST(LoggerTest, InsertStringAfterOccurrence) {
    Logger logger;

    // Test empty log list
    EXPECT_EQ(logger.logs_.size(), 0);
    logger.insertStringAfterOccurrence("target", "newEntry");
    EXPECT_EQ(logger.logs_.size(), 1);

    // Test with existing log entries
    logger.logs_.emplace_front(LogEntry{"existing1"});
    logger.logs_.emplace_front(LogEntry{"target"});
    logger.logs_.emplace_back(LogEntry{"existing2"});

    EXPECT_EQ(logger.logs_.size(), 3);
    logger.insertStringAfterOccurrence("target", "newEntry");
    EXPECT_EQ(logger.logs_.size(), 4);
    EXPECT_EQ(logger.logs_.front().content, "existing1");
    EXPECT_EQ(logger.logs_[1].content, "target");
    EXPECT_EQ(logger.logs_[2].content, "newEntry");
}
```']

