const { MongoClient } = require('mongodb');
const axios = require('axios');
const Bluebird = require('bluebird');
const asyncPool = require('async-pool');
const exponentialBackoff = require('exponential-backoff');
const logger = require('winston');

class DataPipeline {
  constructor(apiUrl, dbUrl, collectionName) {
    this.apiUrl = apiUrl;
    this.dbUrl = dbUrl;
    this.collectionName = collectionName;
    this.client = null;
    this.db = null;
    this.isPaused = true;
  }

  async initialize() {
    this.client = await MongoClient.connect(this.dbUrl, { useNewUrlParser: true });
    this.db = this.client.db();
  }

  async start() {
    if (this.isPaused) {
      this.isPaused = false;
      this.dataStreamer = new DataStreamer(this.apiUrl, this.handleData.bind(this));
      this.dataStreamer.start();
    }
  }

  async pause() {
    if (!this.isPaused) {
      this.isPaused = true;
      this.dataStreamer.pause();
    }
  }

  async stop() {
    if (!this.isPaused) {
      this.isPaused = true;
      this.client.close();
      this.dataStreamer.stop();
    }
  }

  async handleData(chunk) {
    // Handle data rate limiting and buffer management here
    const batchSize = 1000;
    if (chunk.length > batchSize) {
      await this.persistDataToDatabase(chunk.slice(0, batchSize));
      chunk = chunk.slice(batchSize);
    }

    try {
      await this.persistDataToDatabase([chunk]);
    } catch (error) {
      logger.error(`Error persisting data: ${error}`);
      // Implement retry mechanism with exponential backoff here
    }
  }

  async persistDataToDatabase(dataChunks) {
    const batchOperations = Bluebird.map(dataChunks, (chunk) => {
