    this.apiUrl = apiUrl;
    this.handleDataFunc = handleDataFunc;
    this.axiosInstance = axios.create({ timeout: 60_000 });
    this.isRunning = false;
  }

  start() {
    if (!this.isRunning) {
      this.isRunning = true;
      const streamRequest = this.axiosInstance.get(this.apiUrl);
      streamRequest.on('data', (chunk) => this.handleDataFunc(chunk));
      streamRequest.on('error', (error) => logger.error(`API error: ${error}`));
    }
  }

  pause() {
    // Implement pause mechanism here, e.g., cancel the current request and stop new ones
  }

  stop() {
