```rust
use std::env;
use image::{imageops, DynamicImage};
use pdf::PdfDocument;
use std::process::Command;
use std::io::Write;

fn convert_jpeg_to_pdf(input: &str, output: &str) {
    let mut cmd = Command::new("mupdf");
    cmd.arg("-q").arg("-").stdin(input).stdout(output);
    cmd.spawn().expect("Failed to spawn 'mupdf' command").wait().expect("Command execution failed.");
}

fn convert_image_to_pdf(image: &DynamicImage, output: &str) {
    let mut pdf = PdfDocument::new();
    let image_bytes = image.write_with_format(image::PNG, (0, 0)).expect("Failed to write image.");
    pdf.add_page();
    pdf.get_current_page().write_all(&image_bytes).unwrap();
    pdf.save(output).unwrap();
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        println!("Usage: {} input.jpeg output.pdf", args[0]);
        return;
    }

    // Read JPEG file, convert to DynamicImage and then to PDF
    let input = &args[1];
    let mut image = image::open(input).unwrap();
    convert_image_to_pdf(&image, &args[2]);
}
