#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/stat.h>

// Logging function for recording command execution status and errors
void log_message(const char *msg) {
    // Implement logging here (e.g., writing to a file, sending to a server, etc.)
}

pid_t safe_fork() {
    pid_t pid = fork();

    if (-1 == pid) {
        log_message("Fork failure");
        return -1;
    }

    if (0 == pid) {
        // Child process
        setsid();
        // Continue with your external command execution logic here
    }

    return pid;
}

void handle_signals(int signum) {
    if (getppid() != 1) {
        // We're not the session leader, so we don't need to handle signals
        return;
    }

    switch (signum) {
        case SIGINT:
        case SIGTERM:
            // Parent process received a termination signal, clean up and exit
            log_message("Received SIGINT or SIGTERM");
            _exit(0);
            break;

        default:
            // Unhandled signals, log the signal number and continue
            log_message("Unhandled signal");
    }
}

void install_signal_handler() {
    struct sigaction sa = {};

    sa.sa_handler = handle_signals;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;

    if (-1 == sigaction(SIGINT, &sa, NULL)) {
        log_message("Failed to install SIGINT handler");
    }

    if (-1 == sigaction(SIGTERM, &sa, NULL)) {
        log_command("Failed to install SIGTERM handler");
    }
}

void execute_command(const char *cmd) {
    pid_t child_pid = safe_fork();

    if (-1 == child_pid) {
        log_message("Safe fork failure");
        return;
    }

    int status;
    waitpid(child_pid, &status, WUNTRACED);

    if (WIFEXITED(status)) {
        // Command finished normally
        log_message("Command completed with exit code: %d", WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        // Command was terminated by a signal
        log_message("Command killed by signal: %d", WTERMSIG(status));
    } else if (WIFSTOPPED(status)) {
        // Command was stopped (e.g., due to SIGTSTP)
        log_message("Command stopped with signal: %d", WSTOPSIG(status));
    } else {
        // Unknown command status
        log_message("Unknown command status");
    }
}

int main() {
    install_signal_handler();

    const char *command = "your-external-command";
    execute_command(command);

    return 0;
}
```

