// Custom include for logging system definitions and structures
#include "logging_system.h"

// Log Level Enumeration
enum LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR,
    FATAL,
    NUM_LOG_LEVELS
};

// Log Destination Enum
enum LogDestination {
    CONSOLE,
    FILE,
    SOCKET,
    NUM_DESTINATIONS
};

// Custom logging system class definition
class Logger {
private:
    enum LogLevel level;
    enum LogDestination destination;
    char* formatStr;
    void (*callbackFunc)(const char*, const char*); // Callback function pointer
    FILE* filePtr; // File descriptor for log file
    int socketDesc; // Socket descriptor for remote logging

    static pthread_mutex_t mutex;

public:
    Logger(enum LogLevel level, enum LogDestination destination, const char* formatStr = "", void (*callbackFunc)(const char*, const char*) = nullptr) {
        this->level = level;
        this->destination = destination;
        this->formatStr = new char[strlen(formatStr) + 1];
        strcpy(this->formatStr, formatStr);
        this->callbackFunc = callbackFunc;
    }

    ~Logger() {
        delete[] this->formatStr;
    }

    void setDestination(enum LogDestination dest) {
        this->destination = dest;
    }

    void setFormatString(const char* formatStr) {
        delete[] this->formatStr;
        this->formatStr = new char[strlen(formatStr) + 1];
        strcpy(this->formatStr, formatStr);
    }

    void setCallbackFunction(void (*callbackFunc)(const char*, const char*)) {
