            self.data = json.load(f)

    def get_service(self, service_name):
        return Service(**self.data[service_name])

    def get_rule(self, rule_name):
        return TransformationRule(**self.data[rule_name])

class CachedAlgo:
    def __init__(self, algo, cache=None, ttl=timedelta(minutes=5)):
        self.algo = algo
        self._cache = cache or TTLCache(maxsize=1000, ttl=ttl)

    def get_recommendations(self, user_profile):
        key = hash(str(user_profile))
        if key in self._cache:
            return self._cache[key]
        recommendations = self.algo.get_recommendations(user_profile)
        self._cache[key] = recommendations
        return recommendations

def recommend_engine(user_profiles, historical_data, config, preferred_algorithms):
    redis_pool = ConnectionPool(host='localhost', port=6379, db=0)
    redis = Redis(connection_pool=redis_pool)

