public class ServiceLayer
{
    private readonly Dictionary<string, IExternalApi> _apis;
    private readonly NoSqlDatabase _database;
    private readonly FeatureFlags _featureFlags;
    private readonly RandomValueGenerator _randomValueGenerator;

    public ServiceLayer(NoSqlDatabase database, FeatureFlags featureFlags, RandomValueGenerator randomValueGenerator)
    {
        _database = database;
        _featureFlags = featureFlags;
        _randomValueGenerator = randomValueGenerator;
        _apis = new Dictionary<string, IExternalApi>();
    }

    public void AddApi(IExternalApi api) => _apis[api.Name] = api;

    public void ProcessData(Data data)
    {
        if (!data.IsValid()) return;

        var api = GetApiForData(data);
        var response = api.GetResponse(data);

        if (response is not SuccessResponse<dynamic> successResponse)
        {
            HandleError(api, response);
            return;
        }

        // Process and store data here
    }

