void initPDUQueue(PDUQueue* queue) {
    queue->data = NULL;
    queue->count = 0;
    queue->head = 0;
    queue->tail = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue(PDUQueue* queue, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&queue->lock);

    // Handle the case where the queue is full and there's no memory for a new PDU.
    if (queue->count == queue->capacity) {
        // Add your error handling logic here, e.g., notify an error handler or drop the PDU.
    }

    queue->data[queue->tail] = *pdu;
    ++queue->tail %= queue->capacity;
    ++queue->count;

    pthread_mutex_unlock(&queue->lock);
}
```

