pub async fn create_http_client(config: &Config) -> Result<Client, reqwest::Error> {
    let mut builder = reqwest::Client::builder();

    if config.tls {
        if let Some(cert_path) = &config.cert_path {
            builder = builder.ssl_context(ContextBuilder::new().add_native_ roots().add_trusted_cert(cert_path)?);
        }

        if let Some(key_path) = &config.key_path {
            builder = builder.ssl_context(builder.ssl_context(ContextBuilder::new().add_native_ roots().add_private_key(key_path)?)?;
        }
    }

    if let Some(timeout) = config.timeout {
        builder = builder.timeout(Duration::from_secs(timeout));
    }

    builder.build()
}
```

