use tokio::sync::mpsc;
use futures::StreamExt;

struct DataIngestion {
    mqtt_handler: Box<dyn Stream<Item = Result<serde_json::Value, MqttError>> + Send + Sync>,
    rest_handler: Box<dyn Stream<Item = Result<serde_json::Value, RestApiError>> + Send + Sync>,
    kafka_stream: KafkaStream,
    // ... other data sources
}

impl DataIngestion {
    async fn run(&mut self) {
        let (tx_mqtt, rx_mqtt) = mpsc::channel(20_000);
        let (tx_rest, rx_rest) = mpsc::channel(20_000);
        // ... channels for other data sources

        let mqtt_task = tokio::spawn(async move {
            self.mqtt_handler
                .for_each(|result| {
                    // validate, transform and store the data
                    tx_mqtt.send(result).await.unwrap();
                    async move {}
                })
        });

        let rest_task = tokio::spawn(async move {
            self.rest_handler
                .for_each(|result| {
                    // validate, transform and store the data
                    tx_rest.send(result).await.unwrap();
                    async move {}
                })
        });

        // ... tasks for other data sources

        // Collect all the tasks and run them concurrently.
        let _ = future::join_all([mqtt_task, rest_task, kafka_stream.process()]).await;
    }
}
