[' Here is an outline for the `UnifiedLogSystem` library. This outline provides a modular structure with classes and functions for the given task. Note that the actual implementation involves many steps, including error handling, asynchronous processing, thread safety, configuration management, and more.

```python
# UnifiedLogSystem

import logging
from typing import Dict, Any, Union, List
import os
import yaml
import message_broker
import database
import cloud_logging

class LoggingSink:
    def log(self, log_entry: Dict[str, Any]) -> None:
        """Log a single entry."""
        raise NotImplementedError("Must be implemented in derived classes.")

class FileBasedLogger(LoggingSink):
    # Implement file-based logging

class CloudBasedLogger(LoggingSink):
    # Implement cloud-based logging

class DBLogger(LoggingSink):
    # Implement database logging

class Activity:
    def __init__(self, user_id: str, activity_type: str, timestamp: float, source_ip: str, location: str, metadata: Dict[str, Any] = None):
        self.user_id = user_id
        self.activity_type = activity_type
        self.timestamp = timestamp
        self.source_ip = source_ip
        self.location = location
        self.metadata = metadata or {}

class LoggingSystem:
    def __init__(self, sinks: List[LoggingSink], broker: message_broker.MessageBroker):
        self.sinks = sinks
        self.broker = broker

    def log(self, activity: Activity) -> None:
        for sink in self.sinks:
            sink.log(activity.to_dict())

        # Enqueue the message to be processed asynchronously
        self.broker.enqueue(activity.to_json_string())

    def add_sink(self, sink: LoggingSink) -> None:
        self.sinks.append(sink)

    def run(self):
        """Run the logging system."""
        while True:
            # Process messages from the queue
            message = self.broker.dequeue()
            if message is not None:
                activity = Activity.from_json(message)
                self.log(activity)

class ConfigurationManager:
    def __init__(self, config_file: str):
        with open(config_file) as file:
            self.config = yaml.safe_load(file)

    def get_sink_instances(self) -> List[LoggingSink]:
        sink_types = self.config["sinks"]
        sink_instances = []
        for sink_type in sink_types:
            sink_instance = SINK_FACTORY[sink_type]()
            sink_instances.append(sink_instance)
        return sink_instances

    def get_broker_settings(self) -> message_broker.MessageBrokerConfig:
        # Configure the message broker based on the config file

class SINK_FACTORY:
    def __getitem__(cls, item):
        if item == "file":
            return FileBasedLogger
        elif item == "cloud":
            return CloudBasedLogger
        elif item == "db":
            return DBLogger

# Example usage:
def main():
    config_manager = ConfigurationManager("unified_log_system.yaml")
    sinks = config_manager.get_sink_instances()
    broker = message_broker.MessageBroker(**config_manager.get_broker_settings())
    logging_system = LoggingSystem(sinks, broker)
    logging_system.run()
```

