        _ioService.run();  // Start the IO service immediately if it's not already running
    }
    ~ImageProcessor() { _ioService.stop(); }

    bool processImage(const std::string& filePath, const std::string& outputFilePath) {
        try {
            boost::asio::io_service ioService;  // Create a new I/O service for each request
            boost::asio::ip::tcp::resolver resolver(_ioService);
            auto endpoint = resolver.resolve(boost::asio::ip::tcp::resolver::query(_storageUrl));
            boost::asio::ip::tcp::socket socket(_ioService);
            socket.connect(*endpoint);

            std::vector<char> buffer;
            readChunkedFile(filePath, [&](const char* data, size_t length) {
                buffer.insert(buffer.end(), data, data + length);
            });

            boost::iostreams::filtering_streambuf<boost::iostreams::input> input;
            input.push(boost::iostreams::chunk_size(1024)); // Set chunk size for efficient streaming
            input.push(boost::iostreams::input_device(&buffer[0], &buffer[0] + buffer.size()));
            std::istream stream(&input);

            // Perform image processing and write output using in-memory stream
            // ...
            // Replace with your custom logic

            boost::filesystem::ofstream outputFile(outputFilePath, std::ios_base::binary);
            outputFile << stream.rdbuf();

            _logger("Image processing completed successfully");
        } catch (const std::exception& e) {
            _logger(std::string("Error processing image: ") + e.what());
            return false;
        }

        return true;
    }
private:
    void readChunkedFile(const std::string& filePath, std::function<void(const char*, size_t)> callback) {
        // Implement retry logic and fallback mechanisms as needed
        std::ifstream file(filePath, std::ios::binary);
        if (!file.is_open()) throw std::system_error(errno, std::generic_category(), "Failed to open file: " + filePath);

        char buffer[1024];
        while (file.read(buffer, sizeof(buffer))) {
            callback(buffer, file.gcount());
        }
    }

    std::string _storageUrl;
    void (*_logger)(const char* message);
    boost::asio::io_service _ioService;
    std::mutex _dataMutex;
};
```

