    private readonly IDistributedTracing _distributedTracing;
    private readonly IServiceScopeFactory _serviceScopeFactory;
    private readonly IModelUpdater _modelUpdater;
    private readonly IRedisCache _redisCache;

    public DynamicDataProcessor(ILogger<DynamicDataProcessor> logger, IDatasourceValidator datasourceValidator, IMetadataExtractor metadataExtractor, IOutputFormatter outputFormatter, IDistributedTracing distributedTracing, IServiceScopeFactory serviceScopeFactory, IModelUpdater modelUpdater, IRedisCache redisCache)
