        _metadataExtractor = metadataExtractor;
        _outputFormatter = outputFormatter;
        _distributedTracing = distributedTracing;
        _serviceScopeFactory = serviceScopeFactory;
        _modelUpdater = modelUpdater;
        _redisCache = redisCache;
    }

    public async Task IngestDataAsync(string streamId, DataFormat outputFormat, TimeSpan maxProcessingTime, Func<Exception, HttpResponseMessage> errorCallback)
    {
        // Validate data source and perform initial checks
        var validationResult = _datasourceValidator.ValidateStream(streamId);
        if (!validationResult.IsValid)
        {
            return errorCallback(new Exception($"Validation failure: {validationResult.ErrorMessage}", validationResult.HttpStatusCode));
        }

        // Initialize data processing pipeline and perform data ingestion and transformation
        var processingPipeline = CreateProcessingPipeline(streamId, outputFormat);
        await processingPipeline.ProcessAsync(maxProcessingTime);

        // Save metadata for further analysis or downstream processing
        _metadataExtractor.ExtractMetadata(processingPipeline);

        // Update machine learning models if applicable
        _modelUpdater.UpdateModels();
    }

    private ProcessingPipeline CreateProcessingPipeline(string streamId, DataFormat outputFormat)
    {
        var pipeline = new ProcessingPipeline(streamId);

        switch (GetSourceType(streamId))
        {
            case DataSourceType.WebSocket:
                pipeline.AddStage(CreateWebSocketIngestionStage());
                break;
            case DataSourceType.Kafka:
                pipeline.AddStage(CreateKafkaIngestionStage());
                break;
            case DataSourceType.FileUpload:
                pipeline.AddStage(CreateFileUploadIngestionStage());
                break;
        }

        pipeline.AddStage(CreateDataTransformationStage(outputFormat));
        pipeline.AddStage(CreateOutputFormattingStage());

        return pipeline;
    }
}
