from urllib.request import Request, urlopen
import aiohttp
import redis
import base64
import hashlib
import os
import sys
import traceback
import logging
import concurrent.futures

class LogEntry:
    def __init__(self, timestamp, service_name, log_level, message, metadata):
        self.timestamp = timestamp
        self.service_name = service_name
        self.log_level = log_level
        self.message = message
        self.metadata = metadata

class LogAggregator:
    def __init__(self, buffer_size, retry_count, log_server_url):
        self.buffer = queue.Queue(buffer_size)
        self.retry_count = retry_count
        self.log_server_url = log_server_url
        self.redis_client = redis.StrictRedis()

    async def _send_to_log_server(self, entry):
        try:
            response = await aiohttp.post(self.log_server_url, json=entry.json())
            if response.status != 200:
                self.buffer.put(entry)
        except Exception as e:
            self.buffer.put(entry)
            print(f"Error sending log entry to server: {e}")

    def _send_to_log_server_thread(self, entry):
        try:
            request = Request(self.log_server_url, data=json.dumps(entry.json()).encode('utf-8'), method='POST')
            response = urlopen(request)
            if response.getcode() != 200:
                self.buffer.put(entry)
        except Exception as e:
            self.buffer.put(entry)
            print(f"Error sending log entry to server: {e}")

    def send_log_entry(self, entry):
        if self.redis_client.get(hashlib.sha256(json.dumps(entry.json()).encode('utf-8')).hexdigest()):
            print("Log entry already sent")
            return
        self.redis_client.setex(hashlib.sha256(json.dumps(entry.json()).encode('utf-8')).hexdigest(), 10, "1")
        asyncio.run_coroutine_threadsafe(self._send_to_log_server(entry), self.loop)
        # or use threading.Thread(target=self._send_to_log_server_thread, args=(entry,)).start()

class LoggingFramework:
    def __init__(self, buffer_size, retry_count, log_server_url):
        self.log_aggregator = LogAggregator(buffer_size, retry_count, log_server_url)
        self.lock = threading.Lock()
        self.loggers = {}

    def get_logger(self, name):
        if name not in self.loggers:
            self.loggers[name] = Logger(name)
        return self.loggers[name]

    def log(self, name, level, message, metadata=None):
        entry = LogEntry(time.time(), name, level, message, metadata or {})
        with self.lock:
            self.loggers[name].buffer.put(entry)

