    SecureConnectionManager(int connectionPoolSize) : connectionPoolSize(connectionPoolSize) {}

    void enqueueRequest(const TCP_CONNECTION_REQUEST& request) {
        std::lock_guard<std::mutex> lock(requestsMutex);
        requestsQueue.push(request);
        requestsCV.notify_one();
    }

