    }

    void handleRequest() {
        while (true) {
            TCP_CONNECTION_REQUEST request;

            std::unique_lock<std::mutex> lock(requestsMutex);
            requestsCV.wait(lock, [this] { return !requestsQueue.empty(); });
            if (!requestsQueue.empty()) {
                request = requestsQueue.front();
                requestsQueue.pop();
                lock.unlock();
            }

            if (!request.ip.empty() && request.port > 0) {
                boost::asio::ip::tcp::resolver resolver(ioService);
                boost::asio::connect_options connOptions;

                auto it = connectionsMap.find(request.sessionId);
                if (it == connectionsMap.end()) {
                    if (!authenticate(request.ip, request.sessionId)) {
                        std::cerr << "Authentication failed for client: " << request.ip << ':' << request.port << '\n';
                        continue;
                    }

                    boost::asio::ip::tcp::socket socket = resolver.resolve(request.ip, std::to_string(request.port)).await().result();
                    createConnection(socket);
                    connectionsMap[request.sessionId] = std::move(socket);
                } else {
                    socket = it->second;
                }

                // Implement non-blocking data transfer and error handling here
            }
        }
    }

    void run() {
        std::vector<std::thread> threads;
        for (int i = 0; i < connectionPoolSize; ++i) {
            threads.emplace_back(std::thread(&SecureConnectionManager::handleRequest, this));
        }

        ioService.run();
    }
};
