    db.session.commit()

@app.route('/api/transaction', methods=['POST'])
def create_transaction():
    data = request.get_json()
    user_id = data['user_id']
    account_id = data['account_id']
    details = data['details']

    if not Transaction.validate(user_id, account_id, details):
        return jsonify({"error": "Invalid input"}), 400

    transaction = Transaction(user_id=user_id, account_id=account_id, details=details)
    db.session.add(transaction)
    db.session.commit()

    # Start a distributed transaction and log it if successful or failed with error message and stack trace
    rq_task = rq.enqueue(Transaction.commit, transaction)
    return jsonify({"id": transaction.id}), 202

@app.errorhandler(500)
def handle_internal_server_error(e):
    db.session.rollback()
    log_transaction(Transaction(user_id=request.json['user_id'], account_id=request.json['account_id'], details='', is_successful=False, error_message=str(e), stacktrace=traceback.format_exception(etype=type(e), value=e, tb=e.__traceback__)))
    return jsonify({"error": "An internal server error occurred"}), 500

if __name__ == '__main__':
