void push_back(struct node **head, const NFAPI_CRC_INDICATION_PDU_T *data) {
    struct node *node = malloc(sizeof(struct node));
    memcpy(&node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*head == NULL) {
        *head = node;
        node->prev = node->next = NULL;
    } else {
        struct node *current = *head;
        while (current->next != NULL) current = current->next;
        current->next = node;
        node->prev = current;
        node->next = NULL;
    }
}

