void executeFSAWorkflow(int* fsaStates, int numStates, void* fsa, int lastState, Blueslip* blueslip, ExternalDataSource* externalDataSource, const WorkflowConfig* workflowConfig) {
    // Dynamically load the FSA module
    void* fsa_module = dlopen("fsa_module.so", RTLD_LAZY | RTLD_NOW);
    if (!fsa_module) {
