        int state = fsaStates[i];
        if (state == lastState) break;

        Task* task = &tasks[i];
        task->transition_func = transitionFunc;
        task->priority = workflowConfig->priorities[state];
        task->dependencies = workflowConfig->dependencies[state];
    }

    sem_init(&g_mutex, 0, 1);

