        int state = fsaStates[i];
        if (state == lastState) break;

        Task* task = &tasks[i];
        executeTask(blueslip, externalDataSource, task);
    }

    // Wait for all worker threads to finish
    for (int i = 0; i < NUM_WORKER_THREADS; ++i) {
        pthread_join(g_worker_threads[i], NULL);
    }

    dlclose(fsa_module);
}

