import path from 'path';

class TestModuleLoader {
  constructor(cache) {
    this.cache = cache;
  }

  async loadTestModule(modulePath) {
    const cached = this.cache.get(modulePath);
    if (cached) return cached;

    // Load the test module synchronously to get the class constructor
