2. C Function for Memory Allocation (using Pthreads):

```c
#include <pthread.h>
#include <stddef.h>
#include <stdio.h>

typedef struct {
    size_t size;
    void** array;
} ThreadSafeArray;

void* threadsafe_array_init(ThreadSafeArray* array, size_t size) {
    pthread_mutex_init(&array->mutex, NULL);
    array->size = size;
    array->array = malloc(sizeof(void*) * size);
    return array;
}

void threadsafe_array_destroy(ThreadSafeArray* array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->array);
}

void* threadsafe_array_push(ThreadSafeArray* array, void* data) {
    pthread_mutex_lock(&array->mutex);
    void** new_arr = realloc(array->array, sizeof(void*) * (array->size + 1));
    if (!new_arr) {
        pthread_mutex_unlock(&array->mutex);
        return NULL;
    }
    array->array = new_arr;
    array->array[array->size] = data;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return data;
}
```']

