public class RandomValueGenerator
{
    private readonly string _connectionString;
    private readonly TimeSpan _retryInterval = TimeSpan.FromSeconds(5);
    private MySqlConnection _mysqlConnection;

    public float Min { get; set; }
    public float Max { get; set; }
    public bool IsInclusive => true;

    public RandomValueGenerator(string connectionString)
    {
        _connectionString = connectionString;
        RefreshDatabaseValues();
    }

    private async void RefreshDatabaseValues()
    {
        try
        {
            await OpenConnection();
            var command = new MySqlCommand("SELECT Min, Max FROM RandomValueRange", _mysqlConnection);
            var min = (float)command.ExecuteScalar();
            var max = (float)command.ExecuteScalar();
            this.Min = min;
            this.Max = max;
        }
        catch (Exception ex)
        {
            // Log error and retry after _retryInterval
        }
    }

    private async Task OpenConnection()
    {
        if (_mysqlConnection == null || _mysqlConnection.State != System.Data.ConnectionState.Open)
        {
            _mysqlConnection = new MySqlConnection(_connectionString);
            await _mysqlConnection.OpenAsync();
        }
    }

    public float GenerateFloat() => UnityEngine.Random.Range(Min, Max);
    public int GenerateInt() => (int)(UnityEngine.Random.Range(Min, Max));

    // Implement additional methods for generating random values outside the range.

    public override string ToString() => $"Range: {Min} - {Max} [{_mysqlConnection?.State}]";
}
