```java
import org.apache.avro.generic.GenericData;
import org.apache.avro.io.DecoderFactory;
import org.apache.avro.specific.SpecificRecordBase;

public class CustomDeserializer {
    private final GenericData datum = new GenericData();
    private final DecoderFactory decoderFactory = DecoderFactory.get();

    public <T extends SpecificRecordBase> T deserialize(byte[] bytes, Class<T> clazz) {
        try {
            org.apache.avro.io.DatumReader<T> reader = new GenericDatumReader<>(clazz);
            T specificRecord = reader.read(null, decoderFactory.binaryDecoder(bytes, 0, bytes.length), datum);
            return specificRecord;
        } catch (Exception e) {
            throw new RuntimeException("Failed to deserialize object", e);
        }
    }
}
```

