import akka.actor.ActorSystem;
import akka.stream.*;
import scala.concurrent.duration.*;

public class EventStream {
    private final ActorSystem system;
    private Source<Data, NotUsed> source;
    private Sink<Data, CompletionStage<Done>> sink;

    public EventStream(ActorSystem actorSystem) {
        this.system = actorSystem;
    }

    public void createPipeline(Source<Data, ?> source, Sink<Data, ?> sink) {
        this.source = source;
        this.sink = sink;

        RunnableGraph<Future<CompletedStage>> graph = Source.fromActorRef(system.actorOf(DataGenerator.create()), system).via(DataProcessor.create())
                .toMat(Sink.foreach(system.eventStream(), system), Keep.right());

        graph.run(system, MaterializedValue.withCompletionStage(AsyncCallback.onComplete(() -> {
            System.out.println("Pipeline terminated");
        })));
    }
}
```

2. DataGenerator:

```java
import akka.actor.*;
import java.util.concurrent.TimeUnit;

public class DataGenerator extends AbstractActor {
    private final Random random;

    public static Props create() {
        return Props.create(DataGenerator.class);
    }

    public DataGenerator() {
        this.random = new Random();
    }

    @Override
    public Receive createReceive() {
        return receiveBuilder()
                .matchEquals("start", ctx -> sendToSelf(new DataMessage()))
                .build();
    }

    private class DataMessage {}

    public void onDataMessage(DataMessage message) throws Exception {
        TimeUnit.SECONDS.sleep(random.nextInt(10));
        getSender().tell(new Data("event"), self());
        log.info("Generated data event");
    }
}
```

3. DataProcessor:

```java
import akka.stream.*;
import java.util.concurrent.ConcurrentHashMap;

public class DataProcessor {
    private static final ConcurrentHashMap<String, Data> buffer = new ConcurrentHashMap<>();

    public static MaterializedValue<SinkShape<Data, CompletionStage<Done>>, MatMaster<? extends GraphStageWithMaterializedValue<FlowShape<Data, Data>, CompletionStage<Done>>>> create() {
        return MaterializedValue.with(
                Builder.create().fromGraph(GraphDSL.create(() -> {
                    ActorRef input = GraphDSL.source(SinkShapeTag.WithRef(FlowShapeTag.Of(Data.class)));
                    ActorRef output = GraphDSL.sink(SinkShapeTag.WithRef(FlowShapeTag.Of(Data.class)));

                    BuildContext ctx = new BuildContext(MaterializedValue.MatSupervisionStrategy.superviseFailureAndRestart(), materializer);

                    UniformFanOutShape fanOut = new UniformFanOutShape(2, ctx);
                    MergeShape merge = new MergeShape(ctx);

                    ctx.add(fanOut.outlets());
                    ctx.add(merge);

                    GraphStageWithMaterializedValue<Data, Data> bufferStage = new BufferStage();
                    GraphStageWithMaterializedValue<Data, Data> dedupeStage = new DedupeStage();

                    ctx.put(fanOut.outlets().toArray()[0], bufferStage);
                    ctx.put(merge.in(), dedupeStage);

                    UnlinkLink link = ctx.addLink(input, fanOut.in());
                    Link mergeInLink = ctx.addLink(merge.in0(), dedupeStage);

                    link.setResponder(bufferStage);
                    mergeInLink.setResponder(dedupeStage);

                    return FlowShape.of(Data.class, Data.class)
                            .withAttributes(FlowAttributes.MATERIALIZED_VALUE(MaterializedValue.asCompletionStage(() -> {
                                CompletionStage<Done> result = bufferStage.onComplete();
                                result.thenApply(__ -> dedupeStage.onComplete());
                                return result;
                            })))
                            .withAttributes(FlowAttributes.WITH_GRAPH_NAME("DataProcessor"));
                })).named("DataProcessor")
        );
    }
}
```

4. BufferStage:

```java
import akka.stream.*;
import java.util.concurrent.ConcurrentHashMap;

public class BufferStage implements GraphStageWithMaterializedValue<Data, Data> {
    private static final ConcurrentHashMap<String, Data> buffer = new ConcurrentHashMap<>();

    @Override
    public GraphStageLogic createLogic(AttributeBag attributes) throws Exception {
        final ActorRef out = getOut();
        GraphStageLogic logic = new GraphStageLogic(attributes) {
            @Override
            public void postStop() {
                buffer.clear();
            }

            @Override
            public void onData(Data data, BoundedBuffer<Data> buffer) {
                String key = data.getKey();
                Data existingData = buffer.get(key);
                if (existingData != null) {
                    buffer.put(key, existingData);
                } else {
                    buffer.put(key, data);
                    out.tell(data, self());
                }
            }
        };

        return logic;
    }
}
```

5. DedupeStage:

```java
import akka.stream.*;

public class DedupeStage implements GraphStageWithMaterializedValue<Data, Data> {
    private static final ConcurrentHashMap<String, AtomicInteger> counts = new ConcurrentHashMap<>();

    @Override
    public GraphStageLogic createLogic(AttributeBag attributes) throws Exception {
        final ActorRef out = getOut();
        GraphStageLogic logic = new GraphStageLogic(attributes) {
            @Override
            public void onData(Data data, BoundedBuffer<Data> buffer) {
                String key = data.getKey();
                AtomicInteger count = counts.getOrDefault(key, new AtomicInteger(0));
                if (count.incrementAndGet() == 1) {
                    out.tell(data, self());
                }
            }
        };

        return logic;
    }
}
```

