Regarding the JavaScript function to recursively traverse a DOM tree:

```javascript
function findElementsBySelector(root, selector, callback) {
    var stack = [root];

    while (stack.length > 0) {
        var currentNode = stack.pop();

        if (currentNode instanceof HTMLCollection || Array.isArray(currentNode)) {
            for (var i = currentNode.length - 1; i >= 0; i--) {
                stack.push(currentNode[i]);
            }
        } else if (currentNode.nodeType === Node.ELEMENT_NODE) {
            if (callback(currentNode)) {
                yield currentNode;
            }

            for (var i = 0, len = currentNode.childNodes.length; i < len; ++i) {
                stack.push(currentNode.childNodes[i]);
            }
        }
    }
}
```

