            var user = await _authenticationService.AuthenticateUserAsync();
            if (user == null) return new HashResult { StatusCode = System.Net.HttpStatusCode.Unauthorized };

            _logger.LogRequest(input, user);

            // Cache lookup and compute hash asynchronously
