            var hashedInput = ComputeHash(input);

            // Store hash in database and update cache
            await _databaseService.StoreHashAsync(hashedInput, user);
            await _cachingService.SetAsync(input, hashedInput);

            return new HashResult { StatusCode = System.Net.HttpStatusCode.OK, Data = hashedInput };
