class FileProcessor {
public:
    virtual ~FileProcessor() {}
    virtual void process(const std::string& filename) = 0;
};

class LineCounter : public FileProcessor {
private:
    std::atomic<unsigned int> lines{0};
    std::mutex mtx;

public:
    void process(const std::string& filename) override {
        std::ifstream file(filename);
        if (!file.is_open()) {
            BOOST_LOG_TRIVIAL(error) << "Could not open file: " << filename;
            return;
        }

        std::string line;
        while (std::getline(file, line)) {
            std::unique_lock<std::mutex> lock(mtx);
            lines++;
        }

        file.close();
    }
};

class WordCounter : public FileProcessor {
private:
    std::atomic<unsigned int> words{0};
    std::map<std::string, unsigned int> word_counts;
    std::mutex mtx;

public:
    void process(const std::string& filename) override {
        std::ifstream file(filename);
        if (!file.is_open()) {
            BOOST_LOG_TRIVIAL(error) << "Could not open file: " << filename;
            return;
        }

        std::string line;
        while (std::getline(file, line)) {
            std::istringstream iss(line);
            std::string word;
            unsigned int count = 0;
            while (std::getline(iss, word, ' ')) {
                std::unique_lock<std::mutex> lock(mtx);
                ++count;
                if (!word_counts.count(word)) {
                    word_counts[word] = count;
                } else {
                    word_counts[word] += count;
                }
            }
        }

        file.close();
    }
};

