require __DIR__ . '/vendor/autoload.php';
use App\Middleware\CacheMiddleware;
use Psr\Http\Server\RequestHandlerInterface as RequestHandler;

// Database connection class
final class DBConnection {
    private $host, $dbname, $user, $pass;

    public function __construct($host, $dbname, $user, $pass) {
        $this->host = $host;
        $this->dbname = $dbname;
        $this->user = $user;
        $this->pass = $pass;
    }

    public function connect() {
        $dsn = "mysql:host={$this->host};dbname={$this->dbname}";
        $pdo = new PDO($dsn, $this->user, $this->pass);
        return $pdo;
    }

    public function closeConnection(PDO $connection) {
        $connection = null; // Automatically closes the connection on garbage collection
    }
}

// Request handler for employee details API endpoint
final class EmployeeHandler implements RequestHandler {
    private $db, $cache;

    public function __construct(DBConnection $db, CacheMiddleware $cache) {
        $this->db = $db;
        $this->cache = $cache;
    }

    public function handle(Psr\Http\Server\RequestInterface $request): Psr\Http\Server\ResponseInterface {
        try {
            $id = (int)$request->getAttribute('supervisorId');
            $this->db->connect();
            $stmt = $this->db->prepare("SELECT name, city, address FROM employees WHERE supervisor_id=?");
            $stmt->execute([$id]);
            $employeeData = $stmt->fetch(PDO::FETCH_ASSOC);
            $this->db->closeConnection($this->db);

            // Fetch additional data from external API (e.g., department and project details)
            $externalApiResponse = callExternalApi($id);
            $departmentData = json_decode($externalApiResponse, true);

            // Cache employee-related data for faster retrieval on subsequent requests
            $this->cache->process($request, function () use ($employeeData, $departmentData) {
                return [
                    'name' => $employeeData['name'],
                    'city' => $employeeData['city'],
                    'address' => $employeeData['address'],
                    'department_id' => $departmentData['department_id'],
                    'project_id' => $departmentData['project_id']
                ];
            });

            return new Slim\Psr7\Response(json_encode($this->cache->getResultForKey($request->getAttribute('supervisorId'))), 200);
        } catch (\Exception $e) {
            error_log($e->getMessage());
            return new Slim\Psr7\Response("An error occurred: {$e->getMessage()}", 500);
        }
    }
}

// Create and run the Slim application with the EmployeeHandler and appropriate middleware
use Slim\Factory\AppFactory;

$app = AppFactory::create();
$dbConfig = getenv('DB_CONFIG'); // Configuration for DB connection (e.g., host, dbname, user, pass)
$cacheMiddleware = new CacheMiddleware($config['cache']);
$employeeHandler = new EmployeeHandler(new DBConnection(...explode(',', $dbConfig)), $cacheMiddleware);
$app->get('/api/employees/{supervisorId}', $employeeHandler);
$app->run();
```

