[' ```c
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <sys/types.h>
#include <semaphore.h>
#include <sqlite3.h> // For external database integration
#include <time.h> // For random number generation

// Define CRC indication structure
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define maximum number of concurrently active structures
#define MAX_CONCURRENT 1000

// Database connection and statement objects
sqlite3 *db;
sqlite3_stmt *insertStmt, *getNextFreeIdxStmt;

// Semaphore for limiting the number of active structures
sem_t semActiveStructures;

// Error handling structure
typedef struct {
    int errCode;
    char msg[256];
} ERROR_T;

// Function to initialize the library
void init() {
    // Initialize semaphore
    sem_init(&semActiveStructures, 0, MAX_CONCURRENT);

    // Open database connection
    sqlite3_open("telecom.db", &db);
}

// Function to close the library
void cleanup() {
    sqlite3_close(db);
}

// Function to get next free index in the table
ERROR_T getNextFreeIdx() {
    // Prepare and execute SQL statement to get next free index
    sqlite3_reset(getNextFreeIdxStmt);
    int rc = sqlite3_step(getNextFreeIdxStmt);

    if (rc == SQLITE_DONE) {
        return (ERROR_T){0, ""};
    } else if (rc != SQLITE_ROW) {
        sprintf(error.msg, "Error: getNextFreeIdx - %s", sqlite3_errmsg(db));
        error.errCode = SQLITE_ERROR;
        return error;
    }

    uint32_t idx = sqlite3_column_int(getNextFreeIdxStmt, 0);
    return (ERROR_T){0, ""};
}

// Function to allocate and initialize a new structure
NFAPI_CRC_INDICATION_PDU_T* allocate() {
    ERROR_T err = getNextFreeIdx();
    if (err.errCode != 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *structPtr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    structPtr->RX_UE_INFORMATION_TAG = rand(); // Set unique tag
    structPtr->RNTI = rand(); // Set RNTI
    structPtr->CRC_INDICATION_REL8_TAG = rand() % 65536; // Set CRC_INDICATION_REL8_TAG with random CRCFLAG

    sem_wait(&semActiveStructures); // Decrement active structures counter

    // Prepare and execute SQL statement to insert new structure into the table
    sqlite3_reset(insertStmt);
    snprintf(sqlite3_mprintf(sqlite3_bind_text(insertStmt, 1, "%d"), structPtr->RX_UE_INFORMATION_TAG);
    sqlite3_bind_int(insertStmt, 2, structPtr->RNTI);
    sqlite3_bind_int(insertStmt, 3, structPtr->CRC_INDICATION_REL8_TAG);
    sqlite3_bind_int(insertStmt, 4, (int)structPtr->CRCFLAG);
    int rc = sqlite3_step(insertStmt);
    if (rc != SQLITE_DONE) {
        sprintf(error.msg, "Error: allocate - %s", sqlite3_errmsg(db));
        error.errCode = SQLITE_ERROR;
        free(structPtr);
        return NULL;
    }

    sem_post(&semActiveStructures); // Increment active structures counter

    return structPtr;
}

// Function to free a structure
void free(NFAPI_CRC_INDICATION_PDU_T* structPtr) {
    if (!structPtr) return;

    sem_wait(&semActiveStructures); // Decrement active structures counter

    // Prepare and execute SQL statement to mark the structure as deleted in the table
    sqlite3_reset(insertStmt);
    snprintf(sqlite3_bind_text(insertStmt, 1, "%d"), structPtr->RX_UE_INFORMATION_TAG);
    int rc = sqlite3_step(insertStmt);
    if (rc != SQLITE_DONE) {
        sprintf(error.msg, "Error: free - %s", sqlite3_errmsg(db));
        error.errCode = SQLITE_ERROR;
    }

    sem_post(&semActiveStructures); // Increment active structures counter

    free(structPtr);
}
